(window.FREALLY_I18N = window.FREALLY_I18N || {})["vi"] = {"hero.headline":"<span class=\"hl-muted\">Xem đôi tay thật chơi nhạc của bạn.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\" data-words=\"Then drag it into your DAW.|Read every note.|Learn how it is played.\">Rồi kéo nó vào DAW của bạn.</span>","hero.cycle":"Rồi kéo nó vào DAW của bạn.|Đọc từng nốt nhạc.|Học cách chơi nó.","hero.sub":"Hợp âm, một giai điệu, một dòng bass và một giai điệu đối, được viết theo bất kỳ phong cách nào, hiển thị thành bản nhạc và được đôi tay chân thực chơi trên những nhạc cụ chân thực, từ piano và guitar cho đến cả một ban nhạc. Kèm theo các bài học nhạc dạy bạn tự mình chơi, sáng tác và phối khí bản nhạc ấy. Ngoại tuyến và 100% không dùng AI.","hero.chipStandalone":"Ứng dụng độc lập","what.title":"Đây là gì","what.p1":"Phần lớn những người dùng trình tạo hợp âm chưa bao giờ thấy các phần nhạc của nó sẽ được chơi như thế nào, và phần lớn những người học một nhạc cụ chưa bao giờ được nhìn cận cảnh đôi tay của một người chơi. Handscore cho bạn thấy cả hai.","what.p2":"Chọn một thể loại, một nghệ sĩ hoặc một nhà sản xuất, và Handscore viết bốn phần nhạc theo phong cách đó: hợp âm, một giai điệu, một dòng bass và một giai điệu đối. Chúng hiện ra thành các tờ bản nhạc trên giá nhạc của nhạc cụ, và đôi tay chân thực chơi chúng theo cách một người chơi nhạc cụ đó sẽ chơi: mỗi ngón tay đặt trên đúng phím mà một nghệ sĩ piano sẽ dùng, mỗi ngăn phím và mỗi lần quạt dây đúng như một nghệ sĩ guitar sẽ làm. Các cây piano đến trước, tiếp theo là guitar và guitar bass, rồi sau đó là mọi họ nhạc cụ, cho đến cả một ban nhạc.","what.p3":"Mỗi nốt được hiển thị ngay tại nơi nó được chơi, mỗi phím piano ghi tên ở mặt trước, nên bạn thấy chính xác những gì đang vang lên. Khi một phần đã ưng ý, hãy kéo nó từ tờ nhạc của nó thẳng lên một track trong DAW của bạn.","what.p4":"Và nó còn dạy học. Các bài học bắt đầu từ ngày đầu tiên bên cây piano, lắng nghe bạn chơi và chuyển sang phần tiếp theo khi bạn đã chơi đúng, rồi tiếp tục với đọc bản nhạc, tiết tấu, luyện tai, nhạc lý, sáng tác ca khúc và viết lời, phối khí bài hát, mix, finger drumming, bộ trống, guitar, guitar cổ điển và bass.","inside.title":"Nó sẽ làm được gì","inside.instruments.title":"Mọi họ nhạc cụ","inside.instruments.body":"Bốn cây piano thật đi trước, tiếp đến là bộ điều khiển pad và bộ trống, guitar và guitar bass; sau đó là organ, nhạc cụ gõ dùng dùi, đàn hạc, nhạc cụ dây kéo vĩ, kèn gỗ và kèn đồng, cho đến cả một ban nhạc, mỗi lần một họ.","inside.hands.title":"Đôi tay chân thực","inside.hands.body":"Hai bàn tay chơi mọi nốt theo cách một người chơi nhạc cụ đó sẽ chơi: đúng ngón tay mà một nghệ sĩ piano sẽ chọn, đúng ngăn phím và cú gảy mà một nghệ sĩ guitar sẽ dùng.","inside.lessons.title":"Bài học âm nhạc","inside.lessons.body":"Các khóa học từ những nốt đầu tiên của bạn trên piano, guitar và bass đến đọc bản nhạc, tiết tấu, luyện tai, nhạc lý, sáng tác ca khúc và viết lời, phối khí bài hát và mix. Chúng lắng nghe bạn chơi, và đọc từng bài học cho bạn nghe khi bạn bật công tắc Đọc to.","inside.drums.title":"Trống","inside.drums.body":"Một máy trống với mẫu âm của riêng bạn trên các pad và một bộ trình tự bước, một bộ điều khiển pad có các pad sáng lên theo từng cú gõ, và một bộ trống do đôi tay và đôi chân của tay trống chơi, cùng các khóa học finger drumming và bộ trống.","inside.sheets.title":"Bốn tờ bản nhạc","inside.sheets.body":"Hợp âm, giai điệu, giai điệu đối và bass, mỗi phần trên một tờ riêng, với mọi nốt sáng lên khi được chơi.","inside.styles.title":"Mọi phong cách mà Freally MIDI Master biết","inside.styles.body":"73 thể loại, 1.507 nghệ sĩ và 833 nhà sản xuất, từ cùng những bộ tạo dựa trên quy tắc.","inside.drag.title":"Kéo MIDI","inside.drag.body":"Từng phần một hoặc cả bốn cùng lúc, kéo từ các tờ nhạc thẳng vào DAW của bạn, hoặc lưu thành tệp MIDI hay thành PDF của các tờ nhạc.","inside.views.title":"Góc nhìn phía trước, từ trên xuống và từ bên cạnh","inside.views.body":"Chuyển giữa các góc nhìn trong khi nhạc đang phát; các tờ nhạc xoay theo để luôn dễ đọc và đôi tay không bao giờ bỏ lỡ một nốt nào.","inside.daw.title":"Trong mọi DAW","inside.daw.body":"CLAP, VST3 và AU, cùng một ứng dụng độc lập. Windows, macOS và Linux.","inside.offline.title":"Ngoại tuyến, không AI","inside.offline.body":"Không tài khoản, không đo lường từ xa, không mạng, không mô hình. Mọi phần nhạc, cách bấm ngón và chuyển động đều đến từ các quy tắc, được một cổng kiểm tra khi dựng bảo đảm chứ không chỉ là lời hứa.","ladder.title":"Con đường đến 1.0, và tiếp tới 2.0","ladder.intro":"Mỗi phiên bản một dòng. Các bài học, finger drumming, máy trống và bộ trống, guitar và guitar bass đến trước 1.0. Sau đó, mỗi phiên bản mang đến một họ nhạc cụ mới, được đôi tay chân thực chơi theo cách một giáo viên sẽ chỉ cho bạn.","ladder.rung.v0.1.0":"Nền móng: plugin tải được dưới dạng CLAP, VST3 và AU lẫn ứng dụng độc lập, đề nghị bạn chấp nhận giấy phép, và mở ra một bàn phím 88 phím với tên của mọi phím.","ladder.rung.v0.2.0":"Những cây piano thật: đại dương cầm, piano cơ, piano đứng và honky-tonk, với các phím chuyển động và vang lên khi chơi.","ladder.rung.v0.3.0":"Đôi tay chân thực trên bàn phím, bấm ngón mọi nốt theo cách một nghệ sĩ piano sẽ làm, cùng sáu mươi hai bài kinh điển thuộc phạm vi công cộng để học và một thanh điều khiển phát để tua qua chúng trong khi vẫn nghe được.","ladder.rung.v0.4.0":"Tạo nhạc theo bất kỳ phong cách nào, đọc bốn tờ nhạc khi chúng sáng lên, và kéo MIDI vào DAW của bạn.","ladder.rung.v0.5.0":"Góc nhìn từ trên xuống và từ bên cạnh, với các tờ nhạc nằm phẳng trên đàn piano, và chuyển đổi liền mạch giữa các góc nhìn.","ladder.rung.lessons-1":"Học từ ngày đầu tiên: một khóa piano lắng nghe bạn chơi và chuyển sang phần tiếp theo khi bạn đã chơi đúng, cùng một công tắc Đọc to để đọc từng bài học cho bạn nghe, với từng chữ sáng lên khi được đọc tới.","ladder.rung.mixer":"Một mixer cho từng phần nhạc, với fader, pan, EQ, hiệu ứng và nén, và bản mix được giữ nguyên khi kéo ra.","ladder.rung.song-view":"Chế độ xem Bài hát: tự tay dựng cả một bài hát từ các đoạn, hoặc bắt đầu từ bản phối của một nghệ sĩ hay một thể loại, rồi xem bài hát được chơi và kéo nó vào DAW của bạn.","ladder.rung.lessons-2":"Thêm các khóa học: đọc bản nhạc, tiết tấu, luyện tai, nhạc lý với Nashville Number System, sáng tác ca khúc và viết lời, phối khí và mix.","ladder.rung.finger-drumming":"Finger drumming trên bộ điều khiển pad có các pad sáng lên theo từng cú gõ, từ nhịp đầu tiên đến những groove hoàn chỉnh.","ladder.rung.drum-kit":"Một bộ trống được sắp đặt và chơi theo cách một tay trống chuyên nghiệp sẽ làm, cùng một máy trống bên cạnh, với một công tắc để chọn cái nào chơi phần trống của bạn.","ladder.rung.live-listening":"Nghe trực tiếp: chơi một nhạc cụ thật hoặc hát qua micro hoặc dây cáp nhạc cụ, và các bài học sẽ nghe thấy, kèm bộ chỉnh âm và hiệu chỉnh độ trễ.","ladder.rung.guitars":"Các cây guitar: guitar dây sắt, guitar dây nylon, guitar điện và guitar chặn tiếng, được đôi tay của một tay guitar bấm phím, gảy dây và quạt dây, có tab trên bản nhạc và hai khóa học guitar.","ladder.rung.bass":"Bass: hai cây guitar bass bốn dây hoặc năm dây và một cây contrabass, chơi bằng ngón tay, slap và pop bởi đôi tay của một tay bass, các cú slide của 808 lướt dọc theo dây, cùng một khóa học bass; và hai cây guitar rock qua một amp riêng của Handscore.","ladder.rung.own-audio":"Âm thanh và MIDI của riêng bạn, được đọc thành các phần nhạc và được đôi tay chơi lại.","ladder.rung.classics":"Nhạc kinh điển: những giai điệu thuộc phạm vi công cộng để xem và nghe.","ladder.rung.realism":"Lượt trau chuốt độ chân thực: ánh sáng, chất liệu và chuyển động được đối chiếu với cảnh chơi đàn quay thật.","ladder.rung.finish":"Hoàn thiện: phần cài đặt, mười tám ngôn ngữ ở mọi nơi, khả năng tiếp cận và tài liệu hướng dẫn.","ladder.rung.v1.0.0-beta.1":"Thông báo cập nhật cùng các phiên bản dùng thử và trả phí.","ladder.rung.v1.0.0":"Bản phát hành công khai đầu tiên.","ladder.rung.v1.1.0":"Piano điện và organ, trong đó organ có bàn phím pedal để chơi dòng bass.","ladder.rung.v1.2.0":"Đàn harpsichord, clavinet, celesta và piano đồ chơi; ukulele, banjo và mandolin.","ladder.rung.v1.3.0":"Nhạc cụ gõ dùng dùi: xylophone, marimba, vibraphone và glockenspiel.","ladder.rung.v1.4.0":"Đàn hạc, koto, sitar và dulcimer núi.","ladder.rung.v1.5.0":"Violin, viola, cello và double bass, kéo vĩ và gảy dây.","ladder.rung.v1.6.0":"Sáo flute, clarinet, các loại saxophone, oboe và sáo recorder.","ladder.rung.v1.7.0":"Kèn trumpet, kèn trombone, kèn cor và kèn tuba.","ladder.rung.play-along":"Chơi theo và chế độ học.","ladder.rung.v2.0.0":"Ban nhạc: mỗi phần trên nhạc cụ riêng, mỗi nhạc cụ có người chơi riêng.","ladder.note":"Một phiên bản hoàn tất đã được dựng và gắn thẻ. Đó không phải là bản tải xuống: chưa có bản tải xuống nào trước 1.0.0.","honest.title":"Hiện giờ nó đang ở đâu","honest.start.title":"Nó đang ở những bước đầu tiên","honest.start.body":"Phiên bản 0.14.0 chạy trong DAW và mở ra với bốn cây đàn piano thật do đôi tay chân thực chơi, nhìn từ phía trước, từ trên xuống hoặc từ bên cạnh, máy quay lướt giữa các góc nhìn trong khi nhạc vẫn chơi. Sáu cây guitar — dây sắt, dây nylon, điện, chặn tiếng, và hai cây guitar rock qua một amp riêng của Handscore — cũng có thể lên sân khấu thay cho chúng, đôi tay của một tay guitar bấm phím, gảy dây và quạt dây bè bạn chọn, với tab và sơ đồ hợp âm trên bản nhạc của bè đó; hoặc ba cây bass — hai cây guitar bass, bốn dây hoặc năm dây, và một cây contrabass — đôi tay của một tay bass chơi đường bass bằng ngón tay, slap và pop, các cú slide của 808 lướt dọc theo dây. Tìm một thể loại, nghệ sĩ hoặc nhà sản xuất, nhấn Tạo, và bốn bè được viết theo phong cách đó, in thành bản nhạc trên giá nhạc của đàn và được đôi tay chơi, sẵn sàng để kéo vào DAW dưới dạng MIDI hoặc âm thanh, chỉnh từng nốt, hoặc xuất ra MIDI hay PDF. Mỗi bè phát qua kênh riêng trong một bàn trộn, có trình chỉnh sửa đường bao để tạo hình, và có thể chơi bằng một nhạc cụ của riêng bạn. Chế độ xem bài hát dựng trọn bài hát từng đoạn một, kèm điểm độ sẵn sàng thành hit và các công cụ của người sáng tác. Có sáu mươi hai bài cổ điển thuộc phạm vi công cộng để học, cùng thanh điều khiển phát để tạm dừng, tua lại và lướt qua bài hát, và chế độ bài học dạy mười lăm khóa học — piano đến khoảng cấp 5, đọc nhạc, tiết tấu, luyện tai, nhạc lý, sáng tác, viết lời, rap, phối khí, trộn âm, đánh trống bằng ngón tay, bộ trống, guitar, guitar cổ điển và bass — lắng nghe khi bạn chơi, qua MIDI hoặc, khi bật Lắng nghe, nghe nhạc cụ thật hay giọng của bạn qua micro hoặc dây cáp. Phần trống được chơi trên một máy trống với mẫu âm của riêng bạn trên các pad và một bộ trình tự bước, hoặc trên một bộ trống, chỉ một công tắc để chuyển giữa hai thứ. Thay vào đó, một bộ điều khiển pad hoặc bộ trống cũng có thể lên sân khấu, đôi tay và tay trống chơi phần trống của vòng lặp, và bạn có thể tự chơi trống của mình vào, hết lớp này đến lớp khác. Mọi nhạc cụ khác và thêm nhiều khóa học sẽ đến qua từng phiên bản, như chiếc thang ở trên cho thấy.","honest.downloads.title":"Chưa có bản tải xuống nào trước 1.0.0","honest.downloads.body":"Không có bản beta trên trang này, không có bản dựng thử và không có quyền truy cập sớm.","honest.network.title":"Bản thân Handscore không bao giờ lên mạng","honest.network.body":"Plugin và ứng dụng độc lập không chứa mã mạng nào, và một cổng kiểm tra khi dựng sẽ thất bại nếu có mã như vậy được thêm vào. Nhạc cụ của riêng bạn mà bạn nạp vào một bè là của bạn: nó chạy trong tiến trình riêng và làm những gì nó vẫn luôn làm. Một phiên bản sau này có thể thêm một tính năng kiểm tra cập nhật, luôn tắt trừ khi bạn tự bật lên, được chạy bởi một chương trình riêng biệt.","site.tagline":"Xem đôi tay thật chơi nhạc của bạn. Rồi kéo nó vào DAW của bạn.","footer.licence":"Phần mềm độc quyền — Bảo lưu mọi quyền. © 2026 Mike Weaver, kinh doanh dưới tên Havoc Software. Không phải mã nguồn mở.","footer.yours":"MIDI bạn tạo ra và kéo vào DAW là của bạn. Tác giả của Handscore không nhận bất kỳ quyền sở hữu nào đối với nó.","featuresPage.lead":"Bốn phần nhạc được viết theo bất kỳ phong cách nào, hiển thị thành bản nhạc và được đôi tay chân thực chơi trên những nhạc cụ chân thực, mọi phần đều kéo thẳng được vào DAW của bạn, cùng các bài học nhạc dạy bạn tự mình chơi, sáng tác và phối khí bản nhạc ấy.","featuresPage.version":"Trang này mô tả những gì Freally Handscore phiên bản 1.0 sẽ làm. Phiên bản hiện tại là 0.14.0: xem con đường đến 1.0 ở trang chủ.","featuresPage.numbers.parts":"phần: hợp âm, giai điệu, giai điệu đối và bass","featuresPage.numbers.genres":"thể loại","featuresPage.numbers.artists":"nghệ sĩ","featuresPage.numbers.producers":"nhà sản xuất","featuresPage.numbers.keys":"phím, mỗi phím ghi tên ở mặt trước","featuresPage.numbers.plugins":"định dạng plugin, cùng một ứng dụng độc lập","featuresPage.numbers.languages":"ngôn ngữ","featuresPage.numbers.ai":"mô hình AI","featuresPage.free.title":"Miễn phí hôm nay","featuresPage.free.body":"Handscore hiện miễn phí: không có gói trả phí, không thuê bao và không tài khoản. Hiện chưa có gì để tải xuống, vì không có bản tải xuống nào trước phiên bản 1.0.0, và các phiên bản sau này có thể được bán.","featuresPage.cards.title":"Phiên bản 1.0 làm được gì","featuresPage.cards.pianos.title":"Bốn cây piano thật","featuresPage.cards.pianos.body":"Một cây đại dương cầm, một cây piano cơ, một cây piano đứng và một cây piano honky-tonk, mỗi cây có các phím chuyển động khi vang lên, và được chơi bằng cùng những giọng piano đã đo đạc như của Freally MIDI Master.","featuresPage.cards.strings.title":"Guitar và guitar bass","featuresPage.cards.strings.body":"Guitar dây sắt, guitar dây nylon, guitar điện và guitar chặn tiếng, với cách bấm phím, gảy dây và quạt dây thật do đôi tay của một tay guitar thực hiện, có tab và sơ đồ hợp âm trên bản nhạc, cùng hai cây guitar rock qua một amp riêng của Handscore; và guitar bass bốn dây hoặc năm dây, cùng contrabass, chơi bằng ngón tay, slap và pop, với các cú slide của 808 lướt dọc theo dây.","featuresPage.cards.hands.title":"Đôi tay chân thực","featuresPage.cards.hands.body":"Hai bàn tay chơi mọi nốt theo cách một người chơi đàn sẽ chơi: đúng ngón tay mà một nghệ sĩ piano sẽ chọn, đúng ngăn phím và cú gảy mà một nghệ sĩ guitar sẽ dùng.","featuresPage.cards.sheets.title":"Bốn tờ bản nhạc","featuresPage.cards.sheets.body":"Hợp âm, giai điệu, giai điệu đối và bass, mỗi phần trên một tờ riêng, với mọi nốt sáng lên khi được chơi.","featuresPage.cards.styles.title":"Mọi phong cách mà Freally MIDI Master biết","featuresPage.cards.styles.body":"Chọn một trong 73 thể loại, 1.507 nghệ sĩ hoặc 833 nhà sản xuất, và cùng những bộ tạo dựa trên quy tắc sẽ viết bốn phần nhạc theo phong cách đó.","featuresPage.cards.yours.title":"Âm thanh và MIDI của riêng bạn","featuresPage.cards.yours.body":"Đưa vào âm thanh hoặc MIDI của riêng bạn, và Handscore sẽ đọc nó thành các phần nhạc để đôi tay chơi.","featuresPage.cards.classics.title":"Nhạc kinh điển","featuresPage.cards.classics.body":"Những bài hát thuộc phạm vi công cộng để học, từ bài hát thiếu nhi và thánh ca Giáng sinh đến quốc ca và các chủ đề cổ điển, mỗi bài được soạn cho hai tay và được đôi tay trên sân khấu chơi. Chỉ hợp âm của chúng mới có thể rời khỏi Handscore.","featuresPage.cards.lessons.title":"Bài học âm nhạc","featuresPage.cards.lessons.body":"Một khóa piano từ ngày đầu tiên, lắng nghe bạn chơi và chuyển sang phần tiếp theo khi bạn đã chơi đúng, rồi các khóa học về đọc bản nhạc, tiết tấu, luyện tai, nhạc lý, sáng tác ca khúc và viết lời, phối khí bài hát, mix, finger drumming, bộ trống, guitar, guitar cổ điển và bass. Bật công tắc Đọc to và từng bài học sẽ được đọc cho bạn nghe, với từng chữ sáng lên khi được đọc tới. Bật công tắc Lắng nghe và các bài học sẽ nghe được nhạc cụ thật hoặc giọng của bạn qua micro hoặc dây cáp, chỉ trên máy tính này.","featuresPage.cards.drums.title":"Máy trống và bộ trống","featuresPage.cards.drums.body":"Một máy trống với mẫu âm của riêng bạn trên các pad, âm thanh của từng pad được tạo hình và các bước được lập trình, cùng một bộ trống chuyên nghiệp do đôi tay và đôi chân của tay trống chơi, chỉ một công tắc để chuyển giữa hai thứ. Một bộ điều khiển pad do đôi tay chân thực chơi, mỗi pad sáng lên khi được gõ. Tạo một mẫu trống, tự chơi mẫu của riêng bạn vào hoặc đưa MIDI trống từ DAW của bạn vào, rồi học finger drumming và bộ trống từ nhịp đầu tiên đến những groove hoàn chỉnh.","featuresPage.cards.songs.title":"Trọn bài hát và một mixer","featuresPage.cards.songs.body":"Tự tay dựng một bài hát từ các đoạn hoặc bắt đầu từ bản phối của một nghệ sĩ, rồi mix từng phần nhạc trên dải kênh riêng của nó, và kéo ra với bản mix được giữ nguyên.","featuresPage.cards.drag.title":"Kéo MIDI","featuresPage.cards.drag.body":"Từng phần một hoặc cả bốn cùng lúc, kéo từ các tờ nhạc thẳng vào DAW của bạn, hoặc lưu thành tệp MIDI hay thành PDF của các tờ nhạc.","featuresPage.cards.views.title":"Góc nhìn phía trước, từ trên xuống và từ bên cạnh","featuresPage.cards.views.body":"Chuyển giữa các góc nhìn trong khi nhạc đang phát; các tờ nhạc xoay theo để luôn dễ đọc và đôi tay không bao giờ bỏ lỡ một nốt nào.","featuresPage.cards.daw.title":"Trong mọi DAW","featuresPage.cards.daw.body":"CLAP và VST3 trên Windows, macOS và Linux, AU trên macOS, cùng một ứng dụng độc lập để làm việc mà không cần DAW.","featuresPage.cards.offline.title":"Ngoại tuyến, không AI","featuresPage.cards.offline.body":"Không tài khoản, không đo lường từ xa, không mạng và không mô hình. Mọi phần nhạc, cách bấm ngón và chuyển động đều đến từ các quy tắc.","featuresPage.compare.title":"Đặt cạnh nhau","featuresPage.compare.intro":"Freally Handscore 1.0 đặt cạnh những công cụ mà mọi người dùng để viết các phần nhạc hoặc để xem piano được chơi. Các ô của sản phẩm khác lấy từ thông tin công khai và các bài đánh giá về chúng, được kiểm tra vào tháng 10 năm 2026; chỗ nào chúng tôi không thể xác nhận, ô đó sẽ ghi rõ.","featuresPage.compare.feature":"Tính năng","featuresPage.compare.row.generate":"Viết hợp âm, giai điệu và dòng bass mới theo các phong cách được gọi tên","featuresPage.compare.legend.yes":"có","featuresPage.compare.legend.no":"không","featuresPage.compare.row.plugin":"Chạy bên trong DAW của bạn dưới dạng plugin","featuresPage.compare.row.hands":"Hiển thị đôi tay 3D chân thực chơi các nốt","featuresPage.compare.note.library":"thư viện bản nhạc riêng","featuresPage.compare.legend.part":"một phần","featuresPage.compare.note.fingers":"số ngón tay, không có bàn tay","featuresPage.compare.row.sheets":"Hiển thị các nốt dưới dạng bản nhạc","featuresPage.compare.legend.unknown":"chưa xác nhận","featuresPage.compare.row.drag":"Kéo MIDI vào DAW của bạn","featuresPage.compare.row.offline":"Hoạt động ngoại tuyến, không dùng AI","featuresPage.compare.summaryTitle":"Tóm lại","featuresPage.compare.summary":"Trong bốn sản phẩm này, chỉ Handscore 1.0 có đủ mọi hàng: các phần nhạc được viết theo các phong cách được gọi tên, đôi tay chân thực chơi chúng, bản nhạc, thao tác kéo vào DAW của bạn và plugin.","featuresPage.compare.theyWinTitle":"Họ hơn ở đâu","featuresPage.compare.theyWin":"Scaler 3 là một trạm làm việc lý thuyết âm nhạc rộng hơn nhiều. Synthesia được làm để học các bản nhạc trên chính bàn phím của bạn; các bài học của Handscore lắng nghe bạn chơi từ phiên bản 0.6, nhưng chơi theo trực tiếp phải chờ đến phiên bản 1.9. AR Pianist đưa nghệ sĩ piano của nó vào căn phòng của bạn bằng thực tế tăng cường, điều mà Handscore không làm.","featuresPage.compare.fineprint":"Scaler, AR Pianist và Synthesia là nhãn hiệu của các chủ sở hữu tương ứng, vốn không liên kết với Freally Handscore. Nếu một ô nào đó sai, hãy cho chúng tôi biết và chúng tôi sẽ sửa lại.","featuresPage.why.title":"Vì sao nó được làm như vậy","featuresPage.why.rules.title":"Quy tắc, không phải mô hình","featuresPage.why.rules.body":"Mọi phần nhạc, mọi cách bấm ngón và mọi chuyển động đều đến từ các quy tắc, không có mô hình ở bất cứ đâu. Cùng một phong cách và cùng một hạt giống ngẫu nhiên luôn cho ra cùng những phần nhạc, lần nào cũng vậy.","featuresPage.why.drag.title":"Thấy gì thì kéo nấy","featuresPage.why.drag.body":"Các tờ nhạc được vẽ từ chính MIDI mà chúng kéo ra, và đôi tay chơi đúng những nốt đó, nên thứ đáp xuống track của bạn chính là thứ bạn đã xem.","featuresPage.why.real.title":"Làm theo kích thước thật","featuresPage.why.real.body":"Mọi nhạc cụ đều được làm theo kích thước thật của nó: bàn phím có kích thước của một cây đàn piano thật, và mỗi phím xoay trên thanh cân bằng của nó giống như một phím thật.","featuresPage.why.local.title":"Mọi thứ ở lại trên máy của bạn","featuresPage.why.local.body":"Không tài khoản, không đo lường từ xa và không đám mây. Plugin và ứng dụng độc lập không bao giờ lên mạng, và một cổng kiểm tra khi dựng sẽ thất bại nếu mã mạng từng được thêm vào.","featuresPage.coming.title":"Những gì vẫn đang đến","featuresPage.coming.intro":"Nói thẳng, vì một danh sách tính năng giấu đi các thiếu sót thì không đáng đọc. Trang này mô tả phiên bản 1.0, và Handscore được xây từng phiên bản một, nên phần lớn những gì trên trang vẫn chưa được làm. Mỗi phiên bản trên con đường đến 1.0 đều được đánh dấu trạng thái.","featuresPage.limits.title":"Những gì 1.0 không làm","featuresPage.limits.export":"Một bài hát có giai điệu trùng với một bài kinh điển hoặc một giai điệu nổi tiếng chỉ rời khỏi Handscore dưới dạng hợp âm.","featuresPage.limits.families":"Nó chơi các cây piano, bộ điều khiển pad và bộ trống, guitar và guitar bass. Mọi họ nhạc cụ khác sẽ đến dần qua từng phiên bản sau 1.0, cho đến cả ban nhạc ở 2.0.","featuresPage.limits.learn":"Các bài học của nó lắng nghe bạn chơi, nhưng đôi tay vẫn chưa theo bạn trực tiếp: chơi theo trên bất kỳ nhạc cụ nào sẽ có ở phiên bản 1.9.","featuresPage.coming.downloads":"Không có bản tải xuống nào trước phiên bản 1.0, và cũng không có trên trang này.","docs.intro":"Handscore đang lớn dần thành đôi tay chân thực trên mọi họ nhạc cụ, với các bài học âm nhạc từ piano, guitar và bass đến đánh trống bằng ngón tay, sáng tác và phối khí bài hát. Cuốn hướng dẫn này lớn lên cùng nó, qua từng phiên bản. Hiện tại nó mô tả những gì phiên bản 0.14.0 làm được: các cây đàn piano và đôi tay, đánh trống bằng ngón tay trên bộ điều khiển pad, máy trống, bộ trống và tay trống của nó, Bản đồ trống, các cây đàn guitar và đôi tay của tay guitar, các cây đàn bass và đôi tay của tay bass, ba góc nhìn, tạo bài hát, bản nhạc, kéo thả và xuất, trình chỉnh sửa, các bài cổ điển, thanh điều khiển phát, các bài học và mười lăm khóa học của chúng, việc lắng nghe nhạc cụ thật hoặc giọng của bạn, bộ chỉnh âm, bàn trộn, trình chỉnh sửa đường bao, nhạc cụ của riêng bạn, chế độ xem bài hát cùng các công cụ sáng tác của nó, và điểm độ sẵn sàng thành hit.","docs.start.title":"Bắt đầu","docs.agreement.title":"Thỏa thuận cấp phép","docs.stage.title":"Sân khấu","docs.pianos.title":"Các cây piano","docs.play.title":"Chơi các phím","docs.hands.title":"Đôi tay","docs.pads.title":"Đánh trống bằng ngón tay","docs.machine.title":"Máy trống","docs.kit.title":"Bộ trống","docs.drummap.title":"Bản đồ trống","docs.guitars.title":"Các cây guitar","docs.basses.title":"Các cây bass","docs.views.title":"Các góc nhìn","docs.generate.title":"Tạo bài hát","docs.sheets.title":"Bản nhạc","docs.tray.title":"Khay bản nhạc","docs.drag.title":"Vào DAW của bạn","docs.edit.title":"Chỉnh sửa nốt","docs.lyrics.title":"Lời bài hát","docs.seeds.title":"Hạt giống và lịch sử","docs.classics.title":"Nhạc kinh điển","docs.transport.title":"Thanh điều khiển phát","docs.lessons.title":"Bài học","docs.listen.title":"Lắng nghe","docs.mixer.title":"Bàn trộn","docs.envelopes.title":"Trình chỉnh sửa đường bao","docs.hosted.title":"Nhạc cụ của riêng bạn","docs.song.title":"Chế độ xem bài hát","docs.songtools.title":"Các công cụ sáng tác","docs.grade.title":"Điểm độ sẵn sàng thành hit","docs.shortcuts.title":"Phím tắt","docs.project.title":"Dự án của bạn","docs.theme.title":"Sáng và tối","docs.language.title":"Ngôn ngữ","docs.privacy.title":"Quyền riêng tư của bạn","docs.start.p1":"Handscore chạy bên trong DAW của bạn như một nhạc cụ CLAP, VST3 hoặc AU, hoặc chạy riêng như một ứng dụng độc lập. Hãy đặt nó lên một track nhạc cụ.","docs.start.p2":"Chưa có bản tải xuống nào trước phiên bản 1.0.0, và mã nguồn là riêng tư.","docs.agreement.p1":"Lần đầu mở, Handscore hiện ra thỏa thuận cấp phép của nó. Cho đến khi bạn chọn Đồng ý, Handscore không làm gì và không phát ra âm thanh nào.","docs.agreement.p2":"Câu trả lời của bạn được lưu trên máy tính của bạn và dùng chung cho mọi bản Handscore đang mở, trong mọi DAW và trong ứng dụng độc lập. Nếu bạn từ chối, thỏa thuận vẫn ở trên màn hình, sẵn sàng cho bất cứ khi nào bạn đồng ý.","docs.stage.p1":"Bên dưới thanh trên cùng là sân khấu: cây đàn piano bạn đã chọn, với 88 phím, từ A0 đến C8, theo đúng kích thước của một cây đàn piano thật, trải kín chiều rộng cửa sổ. Tên của mỗi phím nằm ở mặt trước của nó — phím trắng in mực tối, phím đen in màu trắng — và ẩn đi khi phím đang được nhấn, nên bạn luôn thấy những nốt nào đang được chơi.","docs.stage.p2":"Nếu máy tính của bạn không thể vẽ 3D, sân khấu sẽ nói rõ điều đó và giải thích cách bật nó lên, thay vì không hiển thị gì.","docs.stage.p3":"Handscore đo xem máy tính của bạn vẽ sân khấu nhanh đến đâu và chọn mức chất lượng mà máy có thể duy trì mượt mà.","docs.pianos.p1":"Bốn cây piano lần lượt lên sân khấu, mỗi lần một cây: Grand Piano, Acoustic Piano, Upright Piano và Honky-Tonk Piano, mỗi cây có hình dáng, lớp hoàn thiện và âm thanh riêng.","docs.pianos.p2":"Nút Chọn chế độ ở góc trên bên trái (hoặc P) mở các lựa chọn của bạn theo danh mục. Trong Nhạc cụ, Nghe thử chơi một câu nhạc ngắn trên một cây piano mà không đổi đàn, còn Chọn đưa nó lên sân khấu, chuyển tiếp mượt mà từ cây trước đó. Lựa chọn của bạn được lưu cùng dự án.","docs.play.p1":"Nhấp vào một phím để nghe nó, hoặc lướt qua các phím để chơi lần lượt từng phím. Mỗi phím đi xuống bằng cách xoay trên thanh cân bằng của nó, được chơi càng mạnh thì xuống càng nhanh, và tên của phím mờ đi khi phím đang xuống rồi hiện lại khi phím nâng lên.","docs.play.p2":"MIDI từ DAW của bạn chơi cây piano và làm các phím của nó chuyển động. Pedal sustain giữ những nốt bạn buông ra cho đến khi bạn nhấc chân khỏi pedal.","docs.hands.p1":"Hai bàn tay chân thực chơi mọi nốt trên sân khấu theo cách một nghệ sĩ piano sẽ chơi: mỗi ngón được chọn cho đoạn nhạc, ngón cái luồn xuống dưới khi chạy gam, vươn tới những hợp âm rộng, và một bàn tay nhấc lên vượt qua tay kia khi bản nhạc đòi hỏi bắt chéo tay. Khi không có gì đang chơi, đôi tay đặt trên phím, sẵn sàng.","docs.hands.p2":"Handscore tính trước tay nào chơi mỗi nốt, và bằng ngón nào, trước khi nhạc vang lên, nên đôi tay đến đúng lúc phím đi xuống.","docs.pads.p1":"Chọn Bộ điều khiển pad trong Chọn chế độ, mục Nhạc cụ, hoặc bật Bộ điều khiển pad trên sân khấu trong thẻ Trống: một bộ điều khiển mười sáu pad bước lên sân khấu, và đôi tay chơi phần trống của vòng lặp trên đó, từng ngón một — ngón trỏ trước, mỗi tay giữ phía của mình — trong khi các bè khác vẫn vang lên. Mỗi pad sáng lên khi được gõ, theo màu của thành phần bộ trống ứng với nó, gõ càng mạnh càng sáng, rồi mờ dần như đèn của một pad thật; khi bật Giảm chuyển động, màu vẫn giữ còn hiệu ứng mờ dần thì không. Dự án của bạn ghi nhớ lựa chọn này.","docs.pads.p2":"Mỗi vòng lặp đều có phần trống riêng, được viết cùng với nó khi bạn nhấn Tạo. Thẻ Trống, nằm sau Bè trầm, hiển thị mười sáu pad của nó: nhấp vào chúng, chơi chúng từ một bộ điều khiển pad hoặc bàn phím qua MIDI, hoặc bật Phím chơi pad và chơi bằng các phím máy tính — 1 2 3 4, Q W E R, A S D F và Z X C V, hàng trên cùng trước. Bố cục Mặc định đặt các nốt General MIDI từ 36 đến 51 lên các pad bắt đầu từ góc dưới bên trái; Biểu diễn đối xứng gương trống kick, trống snare và hi-hat cho hai tay. Học ánh xạ bộ điều khiển của riêng bạn: gõ từng pad khi được yêu cầu, đếm từ góc dưới bên trái. Esc để hủy, còn Quên quay về mặc định thông dụng.","docs.pads.p3":"Phần trống có bản nhạc riêng theo ký âm trống chuẩn, mỗi thành phần nằm trên dòng kẻ hoặc khe của nó, nốt của tay có đuôi hướng lên và nốt của chân hướng xuống. Khi bộ điều khiển pad ở trên sân khấu, bản nhạc này đứng đầu tiên trên giá nhạc, và khi bật số ngón tay, mỗi nốt cho biết tay và ngón chơi nó.","docs.pads.p4":"Để tự chơi trống của bạn vào, nhấn Ghi trong thẻ Trống. Sau phần đếm nhịp, vòng lặp phát, và mỗi lần nó quay lại từ đầu, những gì bạn đã chơi trở thành một lớp mà nó tiếp tục phát cùng: trống kick, rồi trống snare, rồi hi-hat. Hoàn tác lượt rút lớp cuối cùng lại, và Dừng giữ bản thu, được căn theo nốt móc kép nếu Lượng tử hóa đang bật. Dự án của bạn giữ mọi bản thu kèm độ khớp của nó với phách: chọn bất kỳ bản nào, hoặc quay lại trống gốc của vòng lặp.","docs.pads.p5":"Khóa Đánh trống bằng ngón tay trong chế độ bài học dạy điều này từ ngày 1, trên máy trống: mẫu nhịp của bài tập hiện trong các bước của nó dưới sân khấu, các pad tiếp theo sáng lên trước khi đến lượt, pad sai nháy đỏ, và mỗi lần chơi cho biết bạn chơi sớm hay muộn hơn phách bao nhiêu. Các cú gõ của bạn vang lên qua các pad của máy trống, kể cả mẫu âm của riêng bạn. Dấu nhấn và nốt ma chỉ được chấm trên lần chơi bằng các pad cảm nhận được lực gõ, không phải bằng chuột hay phím máy tính.","docs.machine.p1":"Thẻ Trống là một máy trống. Ở trên cùng, công tắc chọn thứ chơi phần trống, và menu Bộ âm chọn một trong bốn bộ âm điện tử của Handscore — Sub, Floor, Neon và Wire — hoặc bộ âm riêng của phong cách. Bên trái, Mẫu đơn liệt kê các âm thanh của bộ âm và của riêng bạn: nhấp vào một âm để nghe, rồi kéo nó lên một pad (giữ Alt, nó thành thêm một lớp). Mười sáu pad nằm ở giữa, Vòng lặp bên phải chứa phần trống gốc của vòng lặp và những bản thu bạn đã chơi vào, còn Chất âm mang lại cho cả bộ âm Độ méo, Độ giòn, Âm sắc và Nghiền bit.","docs.machine.p2":"Chọn một pad để mở âm thanh của nó bên dưới. Một pad có tối đa bốn lớp, được chọn theo lực nhấn hoặc lần lượt, mỗi lớp có mẫu âm, độ lợi, vị trí, cao độ và điểm đầu riêng. Mẫu âm được vẽ thành dạng sóng với các tay nắm để cắt điểm đầu và điểm cuối, cho nó tăng dần vào và giảm dần ra, còn Đảo ngược và Chuẩn hóa thay đổi cách nó phát, không bao giờ thay đổi tệp. Tiếp theo là cao độ và đường bao cao độ của pad, đường bao âm lượng, một bộ lọc thông thấp, thông cao hoặc thông dải với đường bao riêng, độ lợi và vị trí, một nhóm ngắt (một cú gõ làm im các pad khác trong nhóm, như hi-hat đóng cắt hi-hat mở), Tắt tiếng và Độc tấu. Mỗi thay đổi đều nghe được ngay và là một bước hoàn tác; Đặt lại về âm thanh của bộ trả pad về âm thanh gốc của bộ âm.","docs.machine.p3":"Thêm mẫu âm… đưa âm thanh của riêng bạn vào Mẫu đơn, và các tệp âm thanh kéo từ trình duyệt tệp cũng vào đó: WAV, AIFF hoặc FLAC, dài tối đa 30 giây. Tệp quá dài, quá lớn, im lặng hoặc không phải âm thanh sẽ bị từ chối kèm lý do. Handscore giữ bản sao riêng, nên dự án của bạn vẫn phát mẫu âm ngay cả khi tệp bị di chuyển, và Xuất ra PDF liệt kê các mẫu âm mà dự án dùng.","docs.machine.p4":"Bộ trình tự bước dưới âm thanh của pad hiển thị phần trống của vòng lặp thành các bước, mỗi pad một hàng và mười sáu bước mỗi ô nhịp. Nhấp một bước để đặt hoặc xóa một cú gõ, kéo ngang để tô, kéo chuột phải để bỏ các cú gõ và kéo ngược lại để đặt chúng trở lại, rồi đặt lực của từng cú gõ ở làn bên dưới. Độ swing đẩy các nốt móc kép lệch phách trễ hơn, từ 50 đến 75 %. Từ bàn phím: các phím mũi tên di chuyển, Enter đặt hoặc xóa, Delete xóa, còn Page Up và Page Down thay đổi lực. Phần trống mà Tạo đã viết và những bản thu bạn đã chơi vào đều nằm trong các bước, và mỗi chỉnh sửa đều được nghe, thấy và kéo đi ngay lập tức.","docs.kit.p1":"Một công tắc chọn thứ chơi phần trống của bạn: máy trống hay bộ trống. Nó nằm ở đầu thẻ Trống, trên kênh Trống trong bàn trộn và bên cạnh phần trống trong khay bản nhạc. Chuyển đổi trong khi nhạc đang phát không bao giờ làm nhạc dừng: cú gõ tiếp theo vang lên trên cái kia, và nếu phần trống đang ở trên sân khấu, sân khấu lướt từ bộ điều khiển pad sang bộ trống hoặc ngược lại. Dù chọn cái nào thì vẫn là những cú gõ ấy, dự án của bạn giữ lựa chọn này, và một lần kéo âm thanh sẽ phát đúng thứ bạn đã chọn.","docs.kit.p2":"Khi phần trống ở trên sân khấu và bộ trống được chọn, một bộ trống chuyên nghiệp đứng ở đó — trống snare, trống kick, hai tom treo và hai tom sàn, hi-hat, hai crash, một ride, một splash, một china và một chuông bò — với tay trống cầm dùi bằng hai tay, hai chân đặt trên pedal. Mỗi cú gõ rơi đúng chỗ một tay trống sẽ gõ: tay phải bắt chéo sang hi-hat và ride, rudiment và fill chuyền từ tay này sang tay kia, trống kick dưới chân phải và hi-hat dưới chân trái, nhấc gót khi cần dấu nhấn, và chỉ dùng pedal đôi khi một chân không theo kịp. Jazz và ballad được chơi bằng chổi, các phong cách acoustic nhẹ nhàng bằng dùi bó. Mặt trống lún xuống dưới dùi, còn chũm chọe đung đưa rồi lặng dần.","docs.kit.p3":"Bộ trống có âm thanh acoustic riêng, nghe qua micro gần, micro trên cao và micro phòng: ba fader của Chất âm trộn chúng với nhau. Khi bộ trống đang chơi, bản nhạc trống hiển thị cách phân tay — R hoặc L trên nốt của mỗi tay, RF hoặc LF trên nốt của mỗi chân — với gõ chéo dùi và gõ vành được vẽ bằng đầu nốt riêng, nốt ma nằm trong ngoặc, và khi bộ trống ở trên sân khấu, bản nhạc này đứng đầu tiên trên giá nhạc. Những âm thanh pad mà bạn thay đổi trong lúc đó là của máy trống, và sẽ nghe thấy khi bạn chuyển lại.","docs.drummap.p1":"Kéo một tệp MIDI trống từ trình duyệt tệp vào thẻ Trống và nó sẽ thành trống của vòng lặp, mọi nốt giữ nguyên như ban đầu. Bản đồ trống bên cạnh liệt kê từng nốt mà tệp dùng, số lần gõ của nốt đó và nó chơi gì. Đọc theo chọn bố cục mà DAW của bạn đã dùng để ghi tệp — General MIDI, Ableton Drum Rack, FL Studio FPC, Logic Drummer, EZdrummer / Superior Drummer hoặc Addictive Drums — và mỗi hàng có thể đặt thành bất kỳ thành phần nào của bộ trống, thành Không có trong bộ trống, hoặc thành bè trầm 808. Tay trống chơi mọi thay đổi ngay lập tức. Lưu làm cài đặt sẵn giữ một bản đồ của riêng bạn trên máy tính này cho tệp tiếp theo, và dự án của bạn giữ bản đồ mà nó dùng.","docs.guitars.p1":"Sáu cây guitar có thể lên sân khấu: Guitar (dây sắt), Nylon Guitar, Electric Guitar, Muted Guitar, và hai cây guitar rock, Overdriven Guitar và Distortion Guitar. Trong Chọn chế độ, mục Nhạc cụ, thẻ Đàn guitar liệt kê chúng: Nghe thử quạt các hợp âm Đô, La thứ, Fa và Sol trên một cây trước khi bạn chọn nó, còn Chọn đưa nó lên sân khấu. Chuyển đổi trong khi bài hát đang phát không bao giờ làm nó dừng.","docs.guitars.p2":"Hai bàn tay của một tay guitar chơi vòng lặp của bạn, và chỉ có đôi tay được vẽ ra. Tay bấm chơi theo các thế hợp âm mà một người chơi guitar học — hợp âm mở, các thế chặn dạng Mi và dạng La, power chord, hợp âm ba nốt và thế bấm shell — mỗi hợp âm gần hợp âm trước, còn một câu nhạc thì ở thế bấm thuận tay nhất trên cần đàn, đầu ngón tay ấn ngay sau thanh phím. Tay gảy quạt xuống và lên theo nhịp, gảy từng nốt đơn, chơi fingerstyle bằng ngón cái và các ngón, hoặc đặt lòng bàn tay lên dây với Muted Guitar. Trên một câu nhạc nhanh, bàn tay luyến bằng hammer-on và pull-off ở những chỗ một tay guitar sẽ làm vậy, và một cú slide đưa ngón tay trượt dọc dây, nghe như một nốt lướt qua từng phím. Mỗi dây được ấn xuống phím ở chỗ được bấm và rung khi nốt của nó ngân, cú gảy mạnh rung nhiều hơn cú gảy nhẹ, còn dây bị chặn tiếng thì gần như không rung.","docs.guitars.p10":"Overdriven Guitar và Distortion Guitar chơi qua amp riêng của Handscore: một preamp kiểu đèn, một tone stack, một power amp và một thùng loa. Overdriven Guitar có tiếng crunch của hard rock cổ điển, Distortion Guitar có độ high gain của metal. Qua amp, một hợp âm đầy đủ sẽ bị nhòe đục, nên cả hai chơi bè Hợp âm thành power chord, Distortion Guitar thì chơi palm mute, và chơi giai điệu như Electric Guitar chơi. Chúng được chơi trên một cây guitar rock riêng.","docs.guitars.p3":"Một cây guitar chơi một bè trong bài hát của bạn. Trong Chọn chế độ, Chơi chọn Hợp âm, Giai điệu hoặc Bè phụ, còn Đệm chọn điều xảy ra với các bè còn lại: khi tắt Đệm, các bè guitar không chơi sẽ im lặng và bản nhạc của chúng mờ đi; khi bật Đệm, chúng vang lên trên Grand Piano. Dự án của bạn giữ lựa chọn này.","docs.guitars.p4":"Ba góc nhìn cũng dùng được cho guitar. Trước nhìn thẳng vào người chơi, Trên nhìn dọc xuống cần đàn như chính người chơi nhìn, còn Bên cho thấy tay gảy và cần đàn theo mặt nghiêng. Giá nhạc đứng cạnh người chơi, các bản nhạc xoay về phía từng góc nhìn.","docs.guitars.p5":"Bản nhạc của guitar hiển thị các nốt trên khuông nhạc phía trên tab sáu dòng, với sơ đồ hợp âm ở mỗi lần đổi hợp âm, mũi tên quạt dây, slide, dấu luyến của hammer-on và pull-off, và cách bấm ngón khi bật số ngón tay. Xuất ra PDF cũng in cả tab.","docs.guitars.p6":"Nhấn phím dấu phẩy (,) hoặc phím Cài đặt trên thanh trên cùng, rồi ở trang Nhạc cụ, chọn thanh phím đàn của Electric Guitar, các cây guitar rock hoặc các cây guitar bass, mỗi cây được lưu riêng: Kiểu dáng là Vintage, Hẹp-cao, Medium-jumbo hoặc Jumbo, và Chất liệu là Bạc niken hoặc Thép không gỉ. Nó chỉ đổi vẻ ngoài của cần đàn, không bao giờ đổi âm thanh.","docs.guitars.p7":"Để tự chơi guitar, hãy tắt Hiện bàn tay trong Cài đặt. Khi đôi tay đã ẩn, nhấn vào một dây ở một phím để gảy nốt đó: nốt được giữ cho đến khi bạn thả ra, và tên của nó hiện trên cần đàn. Một phím MIDI sẽ chơi dây và phím đàn gần nhất.","docs.guitars.p8":"Hai khóa học trong chế độ bài học dạy guitar, mỗi khóa từ ngày 1 đến ngày 150. Khóa Đàn guitar, chơi trên guitar dây sắt, guitar điện và guitar chặn tiếng, dạy thế bấm và tab trước: hợp âm mở và quạt dây, riff với kỹ thuật đánh pick luân phiên, palm mute, power chord, hợp âm chặn, legato và các gam ngũ cung, fingerpicking, và đọc khóa Sol. Khóa Guitar cổ điển, chơi trên Nylon Guitar, đọc từ khuông nhạc với tab bên dưới: gảy tựa, các dây trầm và ngón cái, giọng và dấu thăng, hợp âm rải, hợp âm, gảy không tựa, luyến và các bài etude. Bật Lắng nghe, và các bài học sẽ nghe được cây guitar của chính bạn.","docs.guitars.p9":"Trong một bài học guitar, mỗi nốt sắp đến hiện thành một chấm màu trên dây và phím của nó, bên trong là số của ngón tay, hiện dần lên trước khi vang và sáng lên đúng phách. Khi bài học chờ bạn, các chấm cho thấy những nốt nó đang chờ, và trước khi bạn chơi, chúng cho thấy toàn bộ thế bấm của bài tập. Thiết lập Chấm trước … ms bên cạnh tempo quyết định chúng hiện sớm bao lâu.","docs.basses.p1":"Ba cây bass có thể lên sân khấu: Pluck Bass và Slap Bass, hai cây guitar bass điện, cùng Upright Bass, một cây contrabass chơi pizzicato. Trong Chọn chế độ, mục Nhạc cụ, thẻ Đàn bass liệt kê chúng: Nghe thử chơi một đường bass ngắn trên một cây trước khi bạn chọn nó, còn Chọn đưa nó lên sân khấu. Một cây bass chơi Bè trầm trong bài hát của bạn, còn Đệm chọn điều xảy ra với các bè còn lại: im lặng và mờ đi, hoặc vang lên trên Grand Piano.","docs.basses.p2":"Hai bàn tay của một tay bass chơi đường bass, và chỉ có đôi tay được vẽ ra. Ở vùng thấp của cần đàn, tay bấm chơi bằng ngón trỏ, ngón giữa và ngón út, mỗi ngón cách nhau một phím, còn ở vùng cao hơn thì mỗi ngón một phím, đổi thế bấm dựa trên một ngón dẫn như cách người chơi bass được dạy; Upright Bass giữ ngón trỏ, ngón giữa và ngón út ở mọi vị trí, đầu ngón tay chặn dây trên mặt cần không phím của nó ngay tại vị trí của chính nốt đó. Tay gảy đi luân phiên hai ngón, rake một ngón sang dây kế tiếp, chơi ghost note, và trên Slap Bass thì slap các dây trầm bằng ngón cái và pop các dây cao bằng một ngón. Trên Upright Bass, tay gảy gảy dây bằng cạnh ngón tay.","docs.basses.p3":"Các cú slide trong một đường bass 808 được tạo ra được chơi như cách một tay bass sẽ chơi: nốt được gảy một lần và ngón tay trượt dọc dây đến nốt đích, nghe như lướt qua từng phím. Khi được kéo vào DAW hoặc xuất ra, bè bass ghi mỗi cú slide thành một cặp nốt chồng lên nhau, mà sampler sẽ chơi thành một cú lướt.","docs.basses.p4":"Pluck Bass và Slap Bass chơi trên bốn dây hoặc năm dây. Nhấn phím dấu phẩy (,) hoặc phím Cài đặt trên thanh trên cùng, rồi ở trang Nhạc cụ, chọn Số dây, 4 hoặc 5. Năm dây thêm một dây Si trầm, nên một đường 808 thấp được chơi đúng cao độ của nó; với bốn dây, một câu nhạc xuống thấp hơn Mi trầm được chơi cao hơn một quãng tám, cả câu cùng lúc. Dù thế nào, bè bass bạn kéo hoặc xuất ra vẫn là đường bass đúng như khi được tạo.","docs.basses.p5":"Bản nhạc của bass hiển thị các nốt trên khóa Fa phía trên tab bốn dòng, năm dòng với năm dây, với ghost note được đánh dấu x, các cú slide, và T và P dưới tab cho slap và pop. Ba góc nhìn, giá nhạc và việc tự chơi bằng tay hoạt động như với guitar: khi đôi tay đã ẩn, nhấn vào một dây ở một phím để gảy nốt đó.","docs.basses.p6":"Khóa Đàn bass trong chế độ bài học dạy bass từ ngày 1 đến ngày 180. Trên Pluck Bass, khóa học bắt đầu với các dây buông và nốt gốc đúng phách, rồi quãng năm và quãng tám khớp chặt với trống kick, các nốt dọc lên cần đàn, gam và hợp âm rải, các groove từ country và valse đến bossa nova, gospel và blues, cùng walking bass; từ ngày 151 là slap và pop trên Slap Bass. Các chấm trên cần đàn chỉ chỗ ngón tay bạn đặt tiếp theo, như trong một bài học guitar, và khi bật Lắng nghe, các bài học sẽ nghe được cây bass của chính bạn.","docs.views.p1":"Xem sân khấu từ phía trước, từ trên xuống hoặc từ bên cạnh. Xoay núm góc nhìn ở góc trên bên phải sân khấu, hoặc nhấn V để sang góc nhìn kế tiếp và Shift+V để về góc nhìn trước. Máy quay lướt từ góc nhìn này sang góc nhìn kế tiếp trong khi nhạc vẫn chơi, và mọi phím, mọi bàn tay, mọi nốt sáng vẫn đúng nhịp. Dự án của bạn ghi nhớ góc nhìn.","docs.views.p2":"Trước là góc nhìn của người chơi, bàn phím lấp đầy cửa sổ. Trên nhìn thẳng xuống phím đàn và đôi tay: đàn grand đóng nắp lại, và các bản nhạc nằm phẳng cạnh nhau trên nắp để bạn đọc; với đàn upright, chúng nằm trên nắp trên. Bên nhìn dọc bàn phím từ đầu âm cao, ngang tầm phím, để thấy hình dáng đôi tay — mỗi ngón cong thế nào và mỗi phím nhấn xuống sâu bao nhiêu — với các bản nhạc trên giá xoay về phía bạn. Ở góc nhìn Bên, công tắc Từ bên trái dưới núm góc nhìn sẽ nhìn từ đầu âm trầm thay vào đó. Nhấp vào một bản nhạc, hoặc nhấn từ 1 đến 6, để xem gần ở bất kỳ góc nhìn nào.","docs.generate.p1":"Bảng bên trái (thẻ của nó ở mép cửa sổ hiện và ẩn bảng) tìm trong 73 thể loại, 1.507 nghệ sĩ và 833 nhà sản xuất. Chọn một và nhấn Tạo, hoặc G: bốn bè — hợp âm, giai điệu, bè phụ và bè trầm — được viết theo phong cách đó, dài 4 hoặc 8 ô nhịp, và đôi tay chơi chúng trên đàn piano.","docs.generate.p2":"Các nút bên cạnh Tạo đặt giọng, thang âm (41 lựa chọn), cảm xúc, nhịp độ (20 đến 999 BPM; kéo con số lên hoặc xuống), độ phức tạp và 4 hoặc 8 ô nhịp, và mỗi nút cho biết bài hát được làm theo gì. Trong DAW, Theo DAW viết theo nhịp độ dự án của bạn, và khi nó đang bật, nút nhịp độ giữ nguyên nhịp độ đó: tắt nó đi để tự đặt nhịp độ của bạn. Ứng dụng độc lập không có Theo DAW. Chơi được sắp các bè cho hai tay; Nguyên bản giữ chúng đúng như đã viết.","docs.sheets.p1":"Mỗi bè được in thành một trang bản nhạc trên giá nhạc của đàn, có tiêu đề và số trang, và tổng phổ của tất cả các bè đặt bên cạnh. Mỗi đầu nốt sáng lên khi vang dưới con trỏ phát đang chạy, và một bè dài tự lật trang khi chơi. Nhấp vào một bản nhạc, hoặc nhấn 1 đến 6, để đưa nó lại gần; Esc để quay lại.","docs.tray.p1":"Dưới sân khấu, khay chứa từng bè với Độc tấu, Tắt tiếng, Khóa và một bản thu mới. Một bè đã khóa sẽ được giữ lại khi bạn tạo lần nữa. Bản thu, Mơ 1–3 và Mơ lại đưa ra ba phiên bản mới của một bè bên cạnh bản bạn đang có: chọn một và giữ lại.","docs.drag.p1":"Kéo một bè từ bản nhạc của nó, hoặc cả bài với Kéo tất cả, thẳng vào DAW của bạn dưới dạng MIDI. Xuất lưu MIDI của một bè hoặc cả bài vào tệp do bạn đặt tên, với lực nhấn của từng nốt, mức âm lượng và pan của từng bè, nhịp độ và số chỉ nhịp.","docs.drag.p2":"Xuất ra PDF ghi bản nhạc kèm trang bìa: tiêu đề, nhịp độ, giọng và thang âm, độ dài, số ô nhịp, số nốt tổng cộng, theo từng bè và từng trang, và các nhạc cụ. Thêm phần ghi công — tác giả, ca sĩ, nhà sản xuất, các sample bạn đã dùng và nguồn của chúng, hãng thu âm — với tên được gợi ý khi bạn gõ.","docs.edit.p1":"Sân khấu, Giai điệu, Hợp âm, Bè phụ và Bè trầm nằm ở phía trên. Thẻ của một bè mở piano roll riêng của nó, với một chấm tắt tiếng, Độc tấu và dấu × để xóa bè. Chọn, di chuyển, kéo dài, xóa, sao chép, dán và nhân bản nốt; nhấp chuột phải và kéo để lấy nốt đi rồi trả lại. Mỗi bè có gain và pan riêng.","docs.edit.p2":"Thu từ bàn phím MIDI vào roll sau khi đếm một hoặc hai ô nhịp. Thu gọn roll theo thang âm của bài, hoặc theo các hàng có nốt: các hàng của thang âm được tô màu và nốt nằm ngoài được đánh dấu. Khi bạn vẽ, nốt hoặc hợp âm tiếp theo được gợi ý mờ mờ; Tab giữ lại, một cú nhấp giữ một nốt, và vẽ ở chỗ khác sẽ xóa gợi ý.","docs.edit.p3":"Bật Hợp âm bên cạnh thanh điều khiển phát và một phím sẽ chơi một hợp âm 3, 4 hoặc 5 nốt theo giọng của bài, bằng chuột, bàn phím máy tính hoặc bàn phím MIDI.","docs.lyrics.p1":"Gõ lời dưới giai điệu hoặc bè phụ, các âm tiết được đánh dấu: chúng được in lên bản nhạc và sáng lên khi được hát. Bộ đếm bên cạnh mỗi dòng cho biết dòng đó có vừa ô nhịp không. Khi bạn gõ, phần còn lại của từ được gợi ý (Tab để nhận) và lỗi chính tả được sửa, trừ khi bạn chạm dấu kiểm hoặc nhấn Shift+Tab để giữ từ của mình.","docs.seeds.p1":"Mỗi lần tạo hiển thị hạt giống của nó, và mỗi bè hiển thị hạt giống bản thu, kèm Sao chép. Dán hạt giống của một bài để tạo lại bài đó, hoặc hạt giống bản thu của một bè để lấy lại bản thu ấy. Lùi và Tiến đi qua mọi lần tạo bạn đã làm, mỗi lần được đưa về chính xác và được giữ qua các lần khởi động lại; một lần tạo mới không bao giờ lặp lại lần cũ.","docs.classics.p1":"Mục Bài kinh điển trong Chọn chế độ có sáu mươi hai bài hát thuộc phạm vi công cộng để học: bài hát thiếu nhi, nhạc Giáng sinh và thánh ca Giáng sinh, dân ca, nhạc spiritual và quốc ca, các chủ đề cổ điển và những bản piano được yêu thích. Mỗi bài được soạn cho hai tay, giai điệu ở tay phải và hợp âm ở tay trái. Tìm theo tên bài hoặc nhà soạn nhạc, rồi chọn Phát.","docs.classics.p2":"Bài cổ điển là để học, không phải để lấy: chỉ hợp âm của nó mới được rời khỏi Handscore. Một bài được tạo có giai điệu, bè phụ hoặc bè trầm giống một giai điệu nổi tiếng sẽ giữ bè đó lại trong ứng dụng, và nói rõ lý do.","docs.transport.p1":"Bên dưới sân khấu: tua lại, phát hoặc tạm dừng, dừng và tua nhanh, cùng một dòng thời gian hiển thị thời gian của bài và một vạch ở mỗi ô nhịp. Di chuột lên dòng thời gian để xem đôi tay tại thời điểm đó trong một bản xem trước nhỏ; nhấp hoặc kéo để đến đó. Nhấn giữ tua lại hoặc tua nhanh để di chuyển nhanh. Dù cách nào, bạn cũng nghe thấy mọi nốt bạn đi qua. Phím cách để phát và tạm dừng, còn các phím mũi tên trên dòng thời gian bước từng ô nhịp.","docs.transport.p2":"Chữ M bên cạnh các phím là máy đếm nhịp. Bật nó lên và một tiếng tích đánh dấu mỗi phách, phách đầu của mỗi ô nhịp cao hơn, trong khi hai chấm của nó hiển thị phách.","docs.transport.p3":"Khi bài hát có lời, bản xem trước trên dòng thời gian hiển thị những lời đang được hát vào lúc đó.","docs.lessons.p1":"Chọn chế độ → Bài học mở chế độ bài học ngay trong studio: bản đồ khóa học và các bước của ngày ở bên trái, sân khấu ở giữa và phần chữ của bài ở bên dưới. Nút Khóa học phía trên bản đồ chọn một trong mười lăm khóa học: Đàn piano, Đọc nhạc, Tiết tấu, Luyện tai, Nhạc lý cho nhà sản xuất, Sáng tác bài hát, Viết lời, Rap và flow, Phối khí bài hát, Trộn âm, Đánh trống bằng ngón tay, Bộ trống, Đàn guitar, Guitar cổ điển và Đàn bass. Mỗi khóa đi từng ngày qua các phần của nó, mỗi ngày là một buổi học có hướng dẫn, kèm một ngày ôn tập mỗi tuần; khóa piano đi từ Nhập môn (ngày 1 đến 90) qua Cơ bản (91 đến 400) đến Trung cấp (401 đến 1.300), khóa đánh trống bằng ngón tay và khóa bộ trống đi từ Nhập môn (ngày 1 đến 30) đến Cơ bản (31 đến 150), hai khóa guitar thì mỗi khóa đi từ ngày 1 đến ngày 150, còn khóa bass đi từ ngày 1 đến ngày 180. Lần đầu, một khóa học mở ở ngày 1; sau đó, Tiếp tục đưa bạn về thẳng khóa học, ngày, bước và từ nơi bạn đã dừng. Ngày nào cũng mở được từ bản đồ, và Thoát bài học quay về bài hát bạn đã để lại.","docs.lessons.p2":"Mỗi bước đọc, làm mẫu hoặc lắng nghe. Xem: đôi tay chơi bài tập ở góc nhìn mà bước chỉ định, chậm nếu bước yêu cầu, có số ngón tay. Thử: các phím cần chơi sáng lên và nhạc chờ bạn. Theo nhịp: đúng tempo sau phần đếm vào, mỗi nốt được so với phách. Chơi trọn bài: chơi từ đầu đến cuối, có phần tóm tắt ở cuối. Mỗi lần chơi nêu ô nhịp và phách và chỉ cách sửa. Một bước đạt sau vài lần chơi đúng liên tiếp, còn một ngày đạt khi bài tập chính được chơi trọn vẹn — đúng nhịp, nếu ngày đó luyện nó theo nhịp. Để luyện, lặp lại vài ô nhịp, chơi một tay trong khi sân khấu chơi tay kia, hoặc đổi tempo; trên thang tempo, nhịp tăng sau ba lần chơi sạch và lùi một bậc sau ba lần sai. Thử cũng dùng được chuột trên các phím của sân khấu; Theo nhịp và Chơi trọn bài cần bàn phím MIDI, hoặc bật Lắng nghe.","docs.lessons.p3":"Đọc to tắt cho đến khi bạn bật. Khi đó giọng đọc của chính máy tính đọc bài, mỗi từ sáng lên khi được đọc. Phím Cách phát và tạm dừng, ⏹ dừng, giữ ⏪ hoặc ⏩ để lùi hoặc tiến; chỉnh tốc độ từ một nửa đến gấp đôi và chọn giọng trong số giọng đã cài. Các đồng hồ cho thấy thời gian trong ngày này và trong tất cả, cùng số ngày bạn đã luyện tập. Tiến độ của bạn ở lại trên máy tính này, giống nhau trong ứng dụng độc lập và trong mọi DAW, và không bao giờ đi vào một dự án.","docs.lessons.p4":"Luyện tai hỏi từng câu một: sân khấu chơi câu hỏi một lần, bạn trả lời trên các phím, rồi câu tiếp theo đến. Trong khóa tiết tấu, tiếng tích bớt dần theo từng chặng, từ mọi phách đến không còn phách nào, cho đến khi bạn tự giữ được nhịp. Nhạc lý cho nhà sản xuất hiển thị bất kỳ bài hát được tạo nào thành bảng hợp âm số Nashville.","docs.lessons.p5":"Các khóa học sáng tạo có những bước Sáng tạo: bạn làm việc trong chế độ xem bài hát, làn lời hoặc lưới flow của nó, Bàn trộn hoặc một trang sổ tay, và Kiểm tra cho biết nó tìm thấy gì so với từng mục tiêu của bước, theo cách nói của người sáng tác hoặc của kỹ sư âm thanh. Một mục tiêu bạn cố ý phá vỡ có thể được đánh dấu cố ý, và khi đó nó được tính là đạt. Những bài học này làm việc trên bài hát học tập của riêng bạn, được giữ cùng tiến độ của bạn, và trên các vòng lặp bài học: bài hát và bản trộn của dự án bạn vẫn y nguyên như cũ khi bạn rời chế độ bài học.","docs.lessons.p6":"Khóa Bộ trống đưa bộ trống lên sân khấu và được chơi trên một bộ trống điện tử qua MIDI, trên một bộ trống acoustic khi bật Lắng nghe, hoặc bằng chuột và phím máy tính: cách cầm dùi và cú đánh, các rudiment từ đánh đơn đến các kiểu vê, đôi chân, backbeat, nốt ma, hi-hat mở và ride, shuffle và swing, chổi, pedal đôi, fill và trọn hình thức bài, cùng các groove từ rock và funk đến one-drop, bossa nova và jazz, với tiếng tích bớt dần theo từng chặng. Phần trống và nhạc cụ riêng của dự án sẽ trở lại khi bạn rời đi.","docs.listen.p1":"Các bài học có thể nghe một nhạc cụ thật hoặc giọng của bạn. Nhấn L hoặc phím Lắng nghe trên thanh trên cùng để mở hộp thoại Lắng nghe: chọn đầu vào và kênh của nó, hoặc mọi kênh trộn chung, rồi xem mức tín hiệu chuyển động khi bạn chơi, kèm một đèn báo quá mức và tên hợp âm bạn quạt. Nếu không có tín hiệu vào, hộp thoại sẽ báo, và trên Windows và macOS còn chỉ chỗ cho phép micro. Tai nghe sẽ giúp ích: bài học nghe thấy bạn, chứ không phải loa.","docs.listen.p2":"Trong DAW, Handscore nghe qua đầu vào sidechain riêng của nó, tên là Listen, còn các đầu ra vẫn giữ nguyên. Sẽ không nghe thấy gì cho đến khi có một track được gửi vào đó: hộp thoại hướng dẫn cách làm trong Ableton Live, FL Studio và Reaper.","docs.listen.p3":"Mỗi khóa học có thể lắng nghe đều có công tắc Lắng nghe trên thanh bài học, tắt cho đến khi bạn bật. Khi đó các khóa piano, đọc nhạc và nhạc lý nghe các nốt và hợp âm của bạn trong Thử, Theo nhịp, Chơi trọn bài và các câu hỏi; khóa bộ trống nghe trống kick, trống snare và hi-hat của một bộ trống acoustic và đo thời điểm của mọi thành phần khác; các bài luyện của khóa tiết tấu và Rap và flow đo thời điểm tiếng vỗ tay, tiếng gõ hoặc âm tiết của bạn so với tiếng tích; còn luyện tai nhận câu trả lời bạn hát, ở bất kỳ quãng tám nào. Một lần chơi được nghe theo cách này được chấm theo nốt và thời điểm, và có ghi rõ như vậy: lực chạm, pedal và độ dài giữ một nốt chỉ được chấm qua MIDI. Khi Lắng nghe đang bật, các phím MIDI của bạn vẫn phát tiếng nhưng không được chấm.","docs.listen.p4":"Trong các bước lưới flow của Rap và flow, Đọc rap phát bài hát sau phần đếm vào trong khi bạn đọc rap trên nền đó; dừng lại, và lượt của bạn được so thời điểm với các âm tiết bạn đã đặt: bao nhiêu âm tiết được nghe thấy, độ ăn nhịp của bạn, và mỗi âm tiết đến sớm hay trễ bao nhiêu.","docs.listen.p5":"Bộ chỉnh âm của hộp thoại hiển thị nốt và nó cao hay thấp bao nhiêu cent, ổn định khi nốt ngân, với A4 ở bất kỳ mức nào từ 415 đến 466 Hz và tên các dây buông của đàn guitar và đàn bass. Hiệu chỉnh đo thời gian một âm thanh rời Handscore rồi quay trở lại, bằng nối vòng qua một sợi cáp hoặc từ loa của bạn vào micro, hoặc bằng cách chơi theo tiếng tích, để những gì bạn chơi rơi đúng lúc; con số này được giữ cho đầu vào đó trên máy tính này.","docs.listen.p6":"Mọi thứ được nghe trên máy tính này, và chỉ khi đèn có chữ Đang lắng nghe sáng. Không có gì được ghi âm, lưu giữ hay gửi đi: Handscore chỉ giữ các cài đặt lắng nghe của bạn, như đầu vào bạn đã chọn và độ trễ của nó.","docs.mixer.p1":"Nhấn M, hoặc thẻ Bàn trộn, để xem kênh của mọi bè nằm cạnh nhau cùng kênh tổng. Mỗi kênh có một fader, một núm vị trí, EQ ba dải, Phòng, Vọng và Nhiệt, một bộ nén (tắt cho đến khi bạn bật) và núm Hạt, cùng một đồng hồ mức LED và đèn quá mức; kênh tổng có fader, núm Hạt và đồng hồ mức riêng. Kéo fader trong khi giữ Shift để chỉnh tinh, hoặc nhấp đúp vào nó để về 0 dB. Tắt tiếng và độc tấu chuyển mượt thay vì cắt ngang; Ctrl+click vào một nút độc tấu để thêm một bè vào đó. Mỗi thay đổi đều nghe được khi bạn đang chỉnh và thành một bước hoàn tác khi bạn thả tay, và dự án giữ lại bản trộn.","docs.mixer.p2":"Bên dưới các bản nhạc, tay nắm âm thanh của mỗi bè kéo bè đó vào DAW của bạn dưới dạng WAV, xuất qua kênh của nó theo nhịp độ của bài; cả bản trộn được kéo đúng như bạn nghe và nêu tên các bè bị bỏ ra. Kéo MIDI mang theo fader và vị trí của bè dưới dạng controller và cho biết những gì MIDI không mang được.","docs.envelopes.p1":"Trên thẻ của một bè, nút Đường bao mở các đường bao của bè đó: âm lượng, bộ lọc, cao độ, vị trí và Hạt, mỗi đường đều tắt cho đến khi bạn bật. Kéo một điểm, hoặc kéo hình thoi của một đoạn để uốn cong nó; nhấp đúp để thêm điểm, hoặc nhấp đúp vào một điểm để bỏ nó; chọn một điểm để gõ các giá trị của nó, hoặc di chuyển nó bằng phím mũi tên. Mỗi đường bao có độ sâu, tỉ lệ thời gian, theo lực nhấn và theo phím, một vòng lặp được giữ, thời gian khóa theo nhịp độ, kích hoạt lại, liền tiếng hoặc đặt lại mỗi ô nhịp, và chuyển A/B. Bắt đầu từ một hình dạng, sao chép đường bao sang bè khác, hoàn tác và làm lại, hoặc đặt lại tất cả; trong khi bài hát phát, một chấm cho mỗi nốt chạy trên đường cong.","docs.hosted.p1":"Mỗi bè có thể chơi bằng một nhạc cụ VST3 hoặc CLAP của riêng bạn thay cho nhạc cụ của Handscore. Trên thẻ của bè hoặc kênh của nó trong bàn trộn, nút nhạc cụ mở bộ chọn: nhạc cụ của Handscore đứng đầu, rồi đến mọi nhạc cụ mà lần quét tìm thấy trong các thư mục plugin tiêu chuẩn và trong các thư mục bạn thêm vào. Chọn một và bè đó phát qua nhạc cụ ấy, cửa sổ của nó chỉ cách một cú nhấp; dự án giữ plugin cùng âm thanh của nó. Mỗi plugin chạy trong tiến trình riêng, nên plugin nào bị sập chỉ tự dừng chính nó, và độ trễ của nó được bù trừ. Đôi tay vẫn ở trên nhạc cụ của Handscore, và bè đó được kéo dưới dạng MIDI. Một plugin mà dự án của bạn ghi tên nhưng máy tính này không có sẽ được thay bằng nhạc cụ của Handscore, và bè đó sẽ báo cho bạn. Trong phiên bản này, cửa sổ plugin mở được trên Windows.","docs.song.p1":"Nhấn A, hoặc thẻ Phối khí, để mở dòng thời gian của bài hát dưới sân khấu: piano, đôi tay và bản nhạc vẫn trong tầm nhìn khi bạn dựng, và bài hát phát trong lúc thẻ mở, hoặc từ bất kỳ thẻ nào khi được solo. Tạo bài hát cho cả bài hát của một phong cách theo hình thức riêng của nó; chọn một trong các hình thức của nó hoặc hình thức trống, bắt đầu một bài hát trống, hoặc kéo một phong cách từ bảng bên trái lên dòng thời gian. Mỗi hàng là một bè, trống ở cuối, và mỗi ô là một clip.","docs.song.p2":"Thêm, chèn, di chuyển, đổi tên, kéo dài và rút ngắn các đoạn từ phần đầu và menu của chúng; sao chép và dán clip, tách riêng một clip dùng chung, cho clip vào và ra dần từ các góc của nó, đặt số ô nhịp nó lặp lại và khóa những clip mà bản thu mới giữ lại. Gieo lại một đoạn, lặp nó bằng ↻, hoặc nhấp đúp vào một clip để nghe riêng. Lấp một ô bằng cách gửi vòng lặp trên sân khấu tới đó, thả một tệp .mid hoặc tệp âm thanh lên đó từ trình duyệt tệp ở bảng bên trái, hoặc chơi một bản thu vào đó bằng bàn phím MIDI. Biểu tượng ✎ của clip mở các nốt của nó trong trình sửa bè dưới dòng thời gian, nơi mỗi chỉnh sửa thay đổi mọi đoạn dùng chung clip đó. Mỗi thay đổi là một bước Hoàn tác.","docs.song.p3":"Bản nhạc đánh dấu từng đoạn và lật trang khi bài hát phát, và Đến một đoạn trong khay lật tất cả tới đó. Kéo cả bài hát với các đoạn làm điểm đánh dấu, một đoạn bằng tay cầm ở phần đầu của nó hoặc một clip bằng tay cầm riêng, dưới dạng MIDI hoặc âm thanh, vào DAW của bạn. Mơ lại cho ba phiên bản mới của cả bài hát, và Xuất MIDI cùng Xuất ra PDF cũng hoạt động từ chế độ xem bài hát.","docs.songtools.p1":"Trên thẻ Phối khí, nút Làn lời đặt lời của bài hát dưới giai điệu, mỗi âm tiết dưới một nốt: các âm tiết nhấn được đánh dấu, cuối dòng được tô màu theo cách chúng vần với nhau, mỗi đoạn được gắn nhãn sơ đồ vần của nó, và các cụm từ quen thuộc được chỉ ra. Nút Lưới flow mở lưới flow dành cho rap: các âm tiết của mỗi ô nhịp trên lưới móc kép của nó, các vần được tô màu, số đếm bên cạnh mỗi ô nhịp và lời lệch khỏi lưới bao xa.","docs.songtools.p2":"Đặt tên cho bài hát phía trên lời của nó. Phiên bản lưu bài hát dưới một cái tên và cho thấy những gì đã thay đổi từ đó: lời theo từng dòng, các đoạn được thêm, bị bỏ, di chuyển, đổi tên hoặc đổi độ dài, và các nốt mà mỗi bè được thêm hoặc mất đi. Menu của một đoạn tắt một bè ở đó rồi bật lại, và phần đầu của mỗi đoạn hiển thị năng lượng của nó. Trong một bài học, PDF hồ sơ tác phẩm in bản lead sheet kèm ký hiệu hợp âm và lời, trang lời bài hát và báo cáo kỹ thuật sáng tác thành một tệp PDF.","docs.grade.p1":"Phím Độ sẵn sàng thành hit trên thẻ Phối khí mở điểm của bài hát bên cạnh dòng thời gian: một chữ cái và số điểm trên 100 từ mười hai mục kiểm tra về hình thức, các bè và lời, mỗi mục nói nó tìm thấy gì và nhắm tới điều gì. Gõ lời của giai điệu vào ô của nó, mỗi ô nhịp một dòng từ ô nhịp 1, để chấm cả lời. Đây là danh sách kiểm tra của người sáng tác, đo trên chính các nốt của bài hát, và được in trên trang bìa PDF.","docs.shortcuts.p1":"Nhấn ? hoặc phím Phím tắt trên thanh trên cùng để xem mọi phím tắt.","docs.project.p1":"Lưu dự án DAW sẽ giữ bài hát, các chỉnh sửa, bản mix, lời, đàn piano, góc nhìn và phần ghi công, và khi mở lại mọi thứ trở về như cũ.","docs.theme.p1":"Công tắc Giao diện tối ở góc trên bên phải chuyển cửa sổ sang sáng hoặc tối. Handscore ghi nhớ lựa chọn của bạn, và các ứng dụng Freally khác trên máy tính của bạn cũng vậy.","docs.language.p1":"Handscore nói được mười tám ngôn ngữ và khởi động bằng ngôn ngữ hệ thống của bạn.","docs.privacy.p1":"Plugin và ứng dụng độc lập không bao giờ dùng mạng. Nếu Handscore có lúc dừng đột ngột, một báo cáo ngắn sẽ được lưu trên máy tính của bạn và được đưa ra vào lần mở tiếp theo; không có gì được gửi đi trừ khi bạn chọn báo cáo sự cố.","docs.privacy.p2":"Khi một bài học lắng nghe, bộ chỉnh âm hiển thị hoặc một lần hiệu chỉnh đang chạy, những gì Handscore nghe thấy được phân tích trên máy tính của bạn và không bao giờ được ghi âm, lưu giữ hay gửi đi, và một đèn báo cho biết khi nào nó đang lắng nghe.","kit.skip":"Chuyển đến nội dung","kit.nav.site":"Trang web","kit.nav.home":"Trang chủ","kit.nav.features":"Tính năng","kit.nav.documentation":"Tài liệu","kit.nav.changelog":"Nhật ký thay đổi","kit.nav.language":"Ngôn ngữ","kit.nav.allApps":"Tất cả ứng dụng Freally","kit.badge.progress":"v0.14.0 đã xong · tiếp theo là v0.15.0","kit.cta.features":"Xem mọi tính năng","kit.cta.docs":"Đọc tài liệu","kit.price":"Freally Handscore hiện miễn phí, nhưng có thể không miễn phí mãi mãi: các phiên bản sau này có thể được bán.","kit.noDownloads":"Hiện chưa có bản tải xuống, và mã nguồn là riêng tư.","kit.label.overview":"Tổng quan","kit.label.inside":"Bên trong","kit.label.roadmap":"Lộ trình","kit.ladder.done":"Xong","kit.ladder.planned":"Đã lên kế hoạch","kit.ladder.goal":"Mục tiêu","kit.ladder.later":"Về sau","kit.label.honesty":"Trung thực","kit.family.label":"Gia đình Freally","kit.family.title":"<span class=\"hl-muted\">Một gia đình.</span> <span class=\"hl-bright\">Mười ứng dụng.</span>","kit.cta.label":"Những gì đã thay đổi","kit.cta.title":"<span class=\"hl-muted\">Mỗi phiên bản,</span> <span class=\"hl-bright\">đều được ghi lại.</span>","kit.cta.lede":"Nhật ký thay đổi liệt kê mọi thứ đã thay đổi trong Freally Handscore, theo từng phiên bản, bằng cả mười tám ngôn ngữ.","kit.cta.changelog":"Đọc nhật ký thay đổi","kit.footer.thisApp":"Ứng dụng này","kit.footer.family":"Gia đình Freally","kit.status.devVersion":"Đang phát triển · v0.14.0","kit.head.features":"<span class=\"hl-muted\">Mọi thứ nó làm được,</span> <span class=\"hl-bright\">đặt cạnh nhau.</span>","kit.label.numbers":"Qua các con số","kit.numbers.lead":"Mỗi con số đều được đếm từ chính ứng dụng. Không có gì là ước tính, và không có gì được làm tròn lên.","kit.label.free":"Miễn phí hôm nay","kit.label.compare":"So sánh","kit.label.principles":"Nguyên tắc","kit.label.limits":"Giới hạn","kit.states.title":"Ý nghĩa của các trạng thái","kit.states.done":"đã dựng và gắn thẻ, nhưng không phải bản tải xuống trên trang này","kit.states.planned":"vẫn chưa được xây dựng","kit.states.goal":"phiên bản mà con đường này hướng tới","kit.states.later":"sau đó, và chưa được lên lịch","kit.states.ladder":"Xem mọi nấc trên con đường","kit.head.documentation":"<span class=\"hl-muted\">Cách hoạt động,</span> <span class=\"hl-bright\">từng bước một.</span>","kit.search.placeholder":"Tìm kiếm trong tài liệu","kit.docs.contents":"Mục lục","kit.head.changelog":"<span class=\"hl-muted\">Mọi thay đổi,</span> <span class=\"hl-bright\">theo từng phiên bản.</span>","kit.changelog.lede":"Mới nhất trước: mọi thứ đã thay đổi trong Freally Handscore, bằng mọi ngôn ngữ của trang này.","kit.changelog.versions":"Phiên bản","kit.search.none":"Không có gì trên trang này khớp với điều đó.","kit.zoom.close":"Đóng","changelog.4551c0a19ac5":"<span class=\"release__meta\"><span class=\"release__ver\">v0.14.0</span><time class=\"release__date\" datetime=\"2026-10-24\">2026-10-24</time></span>","changelog.f043ff57f36d":"Đàn bass. Đặt một cây guitar bass, một cây slap bass hoặc một cây contrabass lên sân khấu và xem đôi tay của một tay bass chơi đường bass của bạn: fingerstyle với hai ngón đi luân phiên, ngón cái slap và cú pop, contrabass được gảy bằng cạnh ngón tay, các cú slide của một đường 808 lướt dọc theo dây. Chơi trên bốn dây hoặc năm dây. Hai cây guitar rock mới gào thét qua một amp riêng của Handscore. Khóa học bass dạy bass trong ngày 1 đến 180, fingerstyle trước, rồi đến slap.","changelog.6b02e0d363a4":"Đã thêm","changelog.91e7f188f73c":"<strong>Ba cây bass.</strong> Pluck Bass, Slap Bass và Upright Bass, trong Chọn chế độ, mục Nhạc cụ, trên thẻ Đàn bass mới. Một cây bass chơi Bè trầm; Đệm chọn các bè khác có còn vang hay không.","changelog.96abccacb5cb":"<strong>Đôi tay của một tay bass.</strong> Tay bấm chơi mỗi ngón một phím ở các thế bấm cao và bằng ngón trỏ, ngón giữa và ngón út ở các thế bấm thấp, như cách người chơi bass được dạy, đổi thế bấm dựa trên một ngón dẫn; trên contrabass, cách bấm ngón đó giữ nguyên ở mọi vị trí, đầu ngón tay đặt trên mặt cần ngay tại vị trí của chính nốt đó. Tay gảy luân phiên hai ngón, rake qua các dây, slap bằng ngón cái và pop bằng một ngón, và chơi ghost note. Chỉ có đôi tay được vẽ ra.","changelog.7c2a4843abc4":"<strong>Slide 808 trên bass.</strong> Các cú slide của một đường 808 được tạo ra được gảy một lần và lướt dọc theo dây qua từng phím. Khi được kéo hoặc xuất ra, bè bass ghi mỗi cú slide thành cặp nốt chồng lên nhau mà sampler nghe thành một cú lướt.","changelog.67ff4c86be3b":"<strong>Bốn hoặc năm dây.</strong> Cài đặt, Nhạc cụ, Số dây: Pluck Bass và Slap Bass chơi trên bốn dây hoặc năm dây, với một dây Si trầm. Với bốn dây, một câu nhạc xuống thấp hơn Mi trầm được nâng lên một quãng tám cả câu; với năm dây, nó được chơi đúng cao độ của nó. Dù thế nào, bè bạn kéo hoặc xuất ra vẫn là đường bass đúng như khi được tạo.","changelog.c112985081f5":"<strong>Hai cây guitar gào thét.</strong> Overdriven Guitar (hard rock cổ điển với tiếng crunch) và Distortion Guitar (metal high gain), trên thẻ Đàn guitar, chơi qua amp riêng của Handscore: một preamp kiểu đèn, một tone stack, một power amp và một thùng loa. Chúng chơi power chord, Distortion Guitar thì chơi palm mute, trên một cây guitar rock riêng.","changelog.6e87c04f93dc":"<strong>Bản nhạc bass.</strong> Bản nhạc của bass hiển thị khóa Fa phía trên tab bốn dòng (năm dòng với năm dây), với ghost note, slide, cùng chữ T của slap và chữ P của pop dưới tab.","changelog.0131eacaeaf2":"<strong>Khóa học bass.</strong> Ngày 1 đến 180 trên Pluck Bass: đọc khóa Fa và tab, lối gảy hai ngón, nốt gốc, quãng năm và quãng tám, gam, hợp âm rải và groove, walking bass, và từ ngày 151 là slap và pop trên Slap Bass, với các chấm trên cần đàn và Lắng nghe nghe cây bass của chính bạn.","changelog.036bdc5a3264":"<strong>Chấm trên cần đàn bass.</strong> Trong một bài học bass, mỗi nốt sắp đến hiện thành một chấm trên dây và phím của nó, bên trong là số của ngón tay, như với guitar.","changelog.2a6141e43be0":"Đã thay đổi","changelog.9d968cf75169":"<strong>Con trỏ mới.</strong> Một vòng tròn với một chấm ở giữa thay cho mũi tên và bàn tay chỉ: chấm là nơi bạn trỏ, vòng tròn đi theo nó, to ra trên bất cứ thứ gì bạn có thể nhấn và thu nhỏ lại khi bạn nhấn. Mọi con trỏ khác, như con trỏ văn bản và các mũi tên đổi kích thước, vẫn giữ nguyên như cũ.","changelog.b84be741ce89":"<strong>Công tắc sáng xanh lá.</strong> Mọi công tắc đều có màu xám khi tắt, màu trắng khi bạn trỏ vào, và màu xanh lá khi bật, dù bạn có trỏ vào hay không. Tắt tiếng và Độc tấu trên các bè của Phối khí cũng theo quy tắc này.","changelog.ab4c76b623e2":"<span class=\"release__meta\"><span class=\"release__ver\">v0.13.0</span><time class=\"release__date\" datetime=\"2026-10-23\">2026-10-23</time></span>","changelog.5e8ca1878684":"Các cây guitar. Đặt một cây guitar dây sắt, guitar cổ điển, guitar điện hoặc guitar chặn tiếng bằng lòng bàn tay lên sân khấu và xem đôi tay của một tay guitar chơi vòng lặp của bạn: hợp âm theo các thế bấm mà tay guitar vẫn dùng, quạt dây, gảy hoặc rải ngón tùy phong cách, câu nhạc bấm ở chỗ thuận tay nhất trên cần đàn, hammer-on, pull-off và slide ở đúng chỗ một người chơi thật sẽ dùng. Dây đàn được ấn xuống phím và rung khi ngân, còn bản nhạc hiển thị tab kèm sơ đồ hợp âm. Chọn bè mà guitar chơi và các bè khác có còn vang hay không. Hai khóa học guitar, hiện đại và cổ điển, dạy guitar trong ngày 1 đến 150 mỗi khóa, các chấm trên cần đàn chỉ chỗ ngón tay bạn đặt tiếp theo.","changelog.cfeacd97871b":"<strong>Bốn cây guitar.</strong> Guitar (dây sắt), Nylon Guitar, Electric Guitar và Muted Guitar, trong Chọn chế độ, mục Nhạc cụ, trên thẻ Đàn guitar mới. Nghe thử quạt các hợp âm Đô, La thứ, Fa và Sol trên từng cây trước khi bạn chọn. Chuyển đổi trong khi bài hát đang phát không bao giờ làm nó dừng.","changelog.704616c6d4b1":"<strong>Đôi tay của một tay guitar.</strong> Tay bấm chơi theo các thế hợp âm mà một người chơi guitar học — hợp âm mở, các thế chặn dạng Mi và dạng La, power chord, hợp âm ba nốt và thế bấm shell — mỗi hợp âm gần hợp âm trước, còn một câu nhạc thì ở thế bấm thuận tay nhất, đầu ngón tay ấn ngay sau thanh phím. Tay gảy quạt xuống và lên theo nhịp, gảy từng nốt đơn, chơi fingerstyle bằng ngón cái và các ngón, hoặc đặt lòng bàn tay lên dây với guitar chặn tiếng. Chỉ có đôi tay được vẽ ra.","changelog.efb9bd040b56":"<strong>Hammer-on, pull-off và slide.</strong> Trên một câu nhạc nhanh, bàn tay luyến ở những chỗ một tay guitar sẽ luyến, và một cú slide đưa ngón tay trượt dọc dây qua từng phím, nghe như một nốt lướt đi từng phím một.","changelog.643312ac2899":"<strong>Dây đàn biết phản hồi.</strong> Mỗi dây được ấn xuống phím ở chỗ được bấm và rung khi nốt của nó ngân, cú gảy mạnh rung nhiều hơn cú gảy nhẹ, dây bị chặn tiếng gần như không rung, dù đôi tay đang hiện hay ẩn.","changelog.9d87c80cfb58":"<strong>Guitar chơi gì, và Đệm.</strong> Chọn để guitar chơi Hợp âm, Giai điệu hay Bè phụ. Khi tắt Đệm, các bè nó không chơi sẽ im lặng và bản nhạc của chúng mờ đi; khi bật Đệm, chúng vang lên trên Grand Piano. Dự án của bạn giữ lựa chọn này.","changelog.294f2493925b":"<strong>Tab và sơ đồ hợp âm.</strong> Bản nhạc của guitar hiển thị các nốt trên khuông nhạc phía trên tab sáu dòng, sơ đồ hợp âm ở mỗi lần đổi hợp âm, mũi tên quạt dây, slide và dấu luyến hammer-on, pull-off, cùng cách bấm ngón khi bật số ngón tay. Tab cũng có trong Xuất ra PDF.","changelog.1f1d5ca2284e":"<strong>Ba góc nhìn của guitar.</strong> Trước nhìn thẳng vào người chơi, Trên nhìn dọc xuống cần đàn như chính người chơi nhìn, còn Bên cho thấy tay gảy và cần đàn theo mặt nghiêng. Giá nhạc đứng cạnh người chơi, các bản nhạc xoay về phía từng góc nhìn.","changelog.abdfa644b4d6":"<strong>Thanh phím đàn.</strong> Cài đặt có trang Nhạc cụ mới: chọn thanh phím đàn của guitar điện — vintage, hẹp-cao, medium-jumbo hoặc jumbo, bằng bạc niken hoặc thép không gỉ. Nó chỉ đổi vẻ ngoài của cần đàn, không bao giờ đổi âm thanh.","changelog.cdbed4e3256a":"<strong>Tự chơi guitar.</strong> Khi đôi tay đã ẩn, nhấn vào một dây ở một phím để gảy nốt đó, nốt được giữ cho đến khi bạn thả ra, tên của nó hiện trên cần đàn. Một phím MIDI sẽ chơi dây và phím đàn gần nhất.","changelog.6babc793bfef":"<strong>Các khóa học guitar.</strong> Khóa Đàn guitar (trên guitar dây sắt, guitar điện và guitar chặn tiếng) dạy thế bấm và tab trước: hợp âm mở và quạt dây, riff với kỹ thuật đánh pick luân phiên, palm mute, power chord, hợp âm chặn, legato và các gam ngũ cung, fingerpicking, và đọc khóa Sol. Khóa Guitar cổ điển (trên guitar dây nylon) đọc từ khuông nhạc với tab bên dưới: gảy tựa, các dây trầm và ngón cái, giọng và dấu thăng, hợp âm rải, hợp âm, gảy không tựa, luyến và các bài etude. Ngày 1 đến 150 mỗi khóa, với Lắng nghe nghe cây guitar của chính bạn.","changelog.9466a05a46ac":"<strong>Chấm trên cần đàn.</strong> Trong một bài học guitar, mỗi nốt sắp đến hiện thành một chấm màu trên dây và phím của nó, bên trong là số của ngón tay, hiện dần lên trước khi vang và sáng lên đúng phách; khi bài học chờ bạn, các chấm cho thấy những nốt nó đang chờ, và trước khi bạn chơi, toàn bộ thế bấm của bài tập. Đặt độ sớm của các chấm ở bên cạnh tempo.","changelog.e39749a272fe":"<strong>Các phím trên thanh trên cùng.</strong> Lắng nghe, Phím tắt và phím Cài đặt (,) mới giờ là biểu tượng, mỗi cái hiện tên khi bạn trỏ vào, để thanh trên cùng vừa với chiều rộng của nó.","changelog.83ccac5ded77":"<span class=\"release__meta\"><span class=\"release__ver\">v0.12.0</span><time class=\"release__date\" datetime=\"2026-10-19\">2026-10-19</time></span>","changelog.9cc20e44893e":"Nghe trực tiếp. Giờ đây các bài học nghe được nhạc cụ thật và giọng hát thật: bật Lắng nghe cho một khóa học, và khóa piano nghe cây piano acoustic của bạn qua micro, khóa bộ trống nghe trống kick, trống snare và hi-hat của bộ trống acoustic của bạn, Rap và flow nghe các âm tiết của bạn trên phách, còn luyện tai nghe những câu trả lời bạn hát — được chấm theo nốt và thời điểm, như với phím MIDI. Hộp thoại Lắng nghe có một bộ chỉnh âm và tính năng hiệu chỉnh độ trễ. Mọi thứ được nghe trên máy tính của bạn, chỉ khi đèn sáng, và không có gì được ghi âm, lưu giữ hay gửi đi.","changelog.bf779e7e1025":"<strong>Hộp thoại Lắng nghe.</strong> Nhấn L hoặc phím Lắng nghe trên thanh trên cùng: chọn đầu vào và kênh của nó (hoặc mọi kênh, trộn chung), xem mức tín hiệu và đèn quá mức, xem tên hợp âm bạn quạt, và thấy ngay khi không có tín hiệu vào, kèm chỗ cho phép micro trên Windows và macOS. Trong DAW, Handscore nghe qua đầu vào sidechain riêng của nó, tên là Listen, các đầu ra chính không đổi, và hộp thoại hướng dẫn cách gửi một track vào đó trong Ableton Live, FL Studio và Reaper.","changelog.8f4dc2184742":"<strong>Đèn báo.</strong> Một đèn có chữ <em>Đang lắng nghe</em> hiện trên thanh trên cùng, thanh bài học và công cụ flow đúng trong lúc đầu vào đang mở, và chỉ khi đó. Đầu vào chỉ mở khi một bài học đang lắng nghe, bộ chỉnh âm đang hiển thị hoặc một lần hiệu chỉnh đang chạy, và đóng lại trong vài giây sau khi bạn rời bài học, đóng cửa sổ hoặc dừng.","changelog.a25a986acc4c":"<strong>Bài học nghe được bạn.</strong> Mỗi khóa học có thể lắng nghe đều có một công tắc Lắng nghe, tắt cho đến khi bạn bật. Các khóa piano, đọc nhạc và nhạc lý nghe các nốt và hợp âm của một cây piano acoustic hoặc bất kỳ nhạc cụ nào khác, trong Thử, Theo nhịp, Chơi trọn bài và các câu hỏi, với cùng những lần kiểm tra và phản hồi như trên MIDI, được đánh dấu <em>Chấm bằng tai</em>: các nốt và thời điểm, không bao giờ là lực chạm, pedal hay độ dài giữ một nốt. Một hợp âm được tính theo tên các nốt của nó, và những gì sân khấu chơi không bị nhầm là của bạn.","changelog.5c5bfa0fb63d":"<strong>Bộ trống qua micro.</strong> Khóa bộ trống nghe trống kick, trống snare và hi-hat của một bộ trống acoustic, nghe một cú kick cùng lúc với hi-hat thành cả hai, và chấm mọi thành phần khác theo thời điểm.","changelog.10606f858c8b":"<strong>Rap và flow cùng tiết tấu bằng giọng.</strong> Các bài luyện của khóa tiết tấu và Rap và flow đo thời điểm âm tiết, tiếng vỗ tay hoặc tiếng gõ của bạn so với tiếng tích, và <em>Đọc rap</em> của công cụ flow đo thời điểm một lượt đọc rap so với các âm tiết bạn đã đặt, sớm hay trễ, để bạn nghe ra độ ăn nhịp của mình. Không có gì được nhận dạng: không từ ngữ nào và không giọng nói nào.","changelog.a77396ec8a04":"<strong>Luyện tai bằng giọng hát.</strong> Hát câu trả lời của bạn: nó được tính ở bất kỳ quãng tám nào, nên giọng trầm có thể hát thấp hơn một quãng tám.","changelog.9b71e7aedb2c":"<strong>Bộ chỉnh âm.</strong> Nốt và nó cao hay thấp bao nhiêu cent, ổn định khi nốt ngân, với A4 từ 415 đến 466 Hz và tên các dây buông của đàn guitar và đàn bass.","changelog.48248965431c":"<strong>Hiệu chỉnh độ trễ.</strong> Hiệu chỉnh đo thời gian một âm thanh rời Handscore rồi quay trở lại, bằng nối vòng qua một sợi cáp hoặc từ loa của bạn vào micro, hoặc bằng cách chơi theo tiếng tích, và giữ con số đó cho đầu vào ấy trên máy tính này, để những gì bạn chơi rơi đúng lúc.","changelog.6e1e7067accb":"<span class=\"release__meta\"><span class=\"release__ver\">v0.11.0</span><time class=\"release__date\" datetime=\"2026-10-19\">2026-10-19</time></span>","changelog.1208381835ec":"Máy trống và bộ trống. Thẻ Trống giờ là một máy trống thực thụ: đặt mẫu âm của riêng bạn lên các pad, xếp lớp chúng, tạo hình âm thanh của từng pad và lập trình beat từng bước một. Hoặc chuyển phần trống sang một bộ trống acoustic đầy đủ và xem đôi tay, đôi chân của tay trống chơi beat của bạn, mỗi cú đánh đúng chỗ một tay trống thật sẽ chơi. Một công tắc chuyển giữa hai thứ trong khi nhạc đang phát, cú gõ vẫn như nhau dù chọn bên nào. MIDI trống nhập vào được đọc qua một Bản đồ trống mà bạn có thể đặt từng hàng, và khóa Bộ trống dạy bộ trống từ cú đánh đầu tiên đến trọn bài hát trong ngày 1 đến 150.","changelog.7c23af602295":"<strong>Máy trống.</strong> Mười sáu pad, mỗi pad có tối đa bốn lớp theo lực nhấn hoặc lần lượt, cùng cao độ, đường bao cao độ, đường bao âm lượng, bộ lọc với đường bao riêng, độ lợi, vị trí, nhóm ngắt, tắt tiếng và độc tấu của riêng nó. Cắt, cho tăng dần và giảm dần, đảo ngược, chuẩn hóa và chỉnh độ lợi một mẫu âm mà không thay đổi tệp. Mỗi thay đổi là một bước hoàn tác và nghe được ngay.","changelog.89b709b63ac0":"<strong>Các bộ âm trống riêng của Handscore.</strong> Bốn bộ âm điện tử — Sub, Floor, Neon và Wire — mỗi bộ có mọi âm thanh mà phần trống dùng, với ba lớp lực nhấn và hai round robin, và phần trống của một phong cách bắt đầu trên bộ âm hợp với nó. Độ méo, Độ giòn, Âm sắc và Nghiền bit mang lại chất âm cho bộ âm.","changelog.257fba39181e":"<strong>Mẫu âm của riêng bạn trên các pad.</strong> Thả một tệp WAV, AIFF hoặc FLAC từ trình duyệt tệp lên một pad, hoặc thêm bằng <em>Thêm mẫu âm…</em>. Tệp quá dài, quá lớn, im lặng hoặc không phải âm thanh sẽ bị từ chối kèm lý do. Handscore giữ bản sao riêng, nên dự án vẫn phát dù tệp gốc bị di chuyển, và mẫu âm của bạn được liệt kê trong Xuất ra PDF.","changelog.6b00189bd87e":"<strong>Bộ trình tự bước.</strong> Hàng bước của từng pad cho 4 hoặc 8 ô nhịp của vòng lặp: nhấp một bước, tô ngang qua, kéo chuột phải để xóa và kéo ngược lại để khôi phục, đặt lực của từng cú gõ, và thêm swing cho các phách lệch. Mẫu nhịp mà Tạo đã viết và những bản thu bạn đã chơi vào đều nằm trong đó, và mỗi chỉnh sửa đều được nghe, thấy và kéo đi ngay lập tức.","changelog.354397d3cc08":"<strong>Bộ trống.</strong> Một bộ trống chuyên nghiệp trên sân khấu — trống snare, trống kick, hai tom treo và hai tom sàn, hi-hat, hai crash, ride, splash, china và chuông bò — với tay trống cầm dùi bằng hai tay, hai chân đặt trên pedal. Mỗi cú gõ rơi đúng chỗ một tay trống sẽ gõ: tay phải bắt chéo sang hi-hat, rudiment và fill chuyền từ tay này sang tay kia, trống kick và hi-hat dưới chân, và chỉ dùng pedal đôi khi một chân không theo kịp. Chổi cho jazz và ballad, dùi bó cho các phong cách acoustic nhẹ nhàng. Âm thanh acoustic riêng, với micro gần, micro trên cao và micro phòng mà bạn có thể trộn.","changelog.f0b2a589c2a6":"<strong>Máy trống hay bộ trống.</strong> Một công tắc trên thẻ Trống, trên kênh Trống và bên cạnh phần trống trong khay chọn thứ chơi phần trống của bạn. Chuyển đổi trong khi bài hát đang phát không bao giờ làm nó dừng: cú gõ tiếp theo vang lên trên cái kia, và sân khấu chuyển sang nó. Dự án của bạn giữ lựa chọn này, và các lần kéo âm thanh phát đúng thứ bạn đã chọn.","changelog.ae274e274c50":"<strong>Bản đồ trống.</strong> MIDI trống từ DAW của bạn giữ nguyên mọi hàng như ban đầu. Chọn bố cục của DAW (General MIDI, Ableton Drum Rack, FL Studio FPC, Logic Drummer, EZdrummer / Superior Drummer, Addictive Drums) hoặc đặt mỗi hàng thành một thành phần của bộ trống, <em>Không có trong bộ trống</em>, hoặc bè trầm 808, và tay trống chơi ngay lập tức. Lưu các bản đồ của riêng bạn.","changelog.5929431e1824":"<strong>Khóa Bộ trống.</strong> Ngày 1 đến 150 trong chế độ bài học trên một bộ trống điện tử qua MIDI: cách cầm dùi và cú đánh, đánh đơn và đánh kép, paradiddle, flam, drag và các kiểu vê, đôi chân, backbeat, nốt ma, hi-hat mở và ride, shuffle và swing, chổi và dùi bó, pedal đôi, fill và hình thức bài, cùng các groove từ rock và funk đến one-drop, bossa nova và jazz, với tiếng tích bớt dần theo từng chặng.","changelog.92e2bf5a0b9c":"<strong>Đánh trống bằng ngón tay trên máy trống.</strong> Khóa Đánh trống bằng ngón tay giờ chơi qua các pad của máy trống, với mẫu nhịp của bài tập hiển thị bên cạnh sân khấu.","changelog.df6470b1e841":"<span class=\"release__meta\"><span class=\"release__ver\">v0.10.0</span><time class=\"release__date\" datetime=\"2026-10-17\">2026-10-17</time></span>","changelog.6d2456347b5e":"Đánh trống bằng ngón tay. Một bộ điều khiển pad bước lên sân khấu, mười sáu pad của nó sáng lên theo từng cú gõ, và đôi tay chân thực chơi phần trống của vòng lặp của bạn trên đó, từng ngón một. Giờ mỗi vòng lặp đều có phần trống riêng, được in trên một bản nhạc trống. Tự chơi trống của bạn vào trên bất kỳ bộ điều khiển pad nào, hết lớp này đến lớp khác khi vòng lặp quay lại, và giữ những bản thu bạn thích. Khóa Đánh trống bằng ngón tay dạy điều này từ phách đầu tiên đến những groove trọn vẹn.","changelog.9f50ff1513e0":"<strong>Bộ điều khiển pad trên sân khấu.</strong> Chọn nó trong Chọn chế độ, mục Nhạc cụ, hoặc bật nó trong thẻ Trống: một bộ điều khiển pad 4×4, với đôi tay chơi phần trống của vòng lặp trên các pad của nó, ngón trỏ trước, mỗi tay giữ phía của mình. Các bè khác vẫn vang lên. Dự án của bạn ghi nhớ lựa chọn này.","changelog.e64037f005b8":"<strong>Mỗi pad sáng lên khi được gõ.</strong> Mỗi thành phần bộ trống có màu riêng, và lực của cú gõ quyết định pad sáng đến mức nào trước khi mờ dần, như đèn của một pad thật. Khi bật Giảm chuyển động, màu vẫn giữ còn hiệu ứng mờ dần thì không.","changelog.766fe929f61e":"<strong>Trống trên mọi vòng lặp.</strong> Tạo giờ cũng viết phần trống của vòng lặp, từ các bộ tạo trống của MIDI Master. Với bè trầm 808, trống kick và 808 đến như một mẫu nhịp duy nhất, và một bản thu mới của bè trầm mang theo phần trống mới.","changelog.18971f931e55":"<strong>Thẻ Trống.</strong> Mười sáu pad trên màn hình, sau thẻ Bè trầm, có chấm và dấu × riêng. Nhấp vào chúng, chơi chúng từ một bộ điều khiển MIDI, hoặc bật Phím chơi pad và chơi bằng các phím máy tính (1 2 3 4, Q W E R, A S D F, Z X C V). Chọn bố cục Mặc định (các nốt General MIDI từ 36 đến 51 bắt đầu từ pad góc dưới bên trái) hoặc bố cục Biểu diễn đối xứng gương. Học ánh xạ bộ điều khiển của riêng bạn: gõ từng pad khi được yêu cầu.","changelog.d30547a5121a":"<strong>Bản nhạc trống.</strong> Bè Trống được in theo ký âm trống chuẩn, mỗi thành phần nằm trên dòng kẻ hoặc khe riêng của nó, nốt của tay có đuôi hướng lên và nốt của chân hướng xuống. Nó đứng trên giá nhạc cùng các bản nhạc khác (đứng đầu tiên khi bộ điều khiển pad ở trên sân khấu) và có phím số riêng như chúng, đồng thời có mặt trong khay với Độc tấu và Tắt tiếng, và trong PDF. Khi bật số ngón tay, mỗi nốt cho biết tay và ngón chơi nó.","changelog.5fcbc2452dda":"<strong>Tự chơi trống của bạn vào.</strong> Ghi chồng lên vòng lặp sau phần đếm nhịp: mỗi lần vòng lặp quay lại từ đầu, lượt bạn vừa chơi trở thành một lớp mà nó tiếp tục phát cùng, nên bạn có thể thêm trống kick, rồi trống snare, rồi hi-hat. Hoàn tác lượt rút lớp cuối cùng lại, và Dừng giữ bản thu, được căn theo nốt móc kép nếu Lượng tử hóa đang bật. Dự án của bạn giữ mọi bản thu kèm độ chuẩn nhịp của nó; chọn bất kỳ bản nào, hoặc quay lại trống gốc của vòng lặp.","changelog.d5b28d4df7b8":"<strong>Khóa Đánh trống bằng ngón tay.</strong> Ngày 1 đến 150 trong chế độ bài học: ngón trỏ, rồi ngón cái và ngón giữa, backbeat, vị trí đặt trống kick, swing, dấu nhấn và nốt ma, fill, groove theo thể loại, rudiment trên một pad và qua nhiều pad, chùm ba và shuffle, groove tuyến tính, với tiếng tích bớt dần theo từng chặng. Các pad tiếp theo sáng lên trước khi đến lượt, pad sai nháy đỏ, và mỗi lần chơi cho biết bạn sớm hay muộn hơn phách bao nhiêu. Lần chơi bằng chuột hoặc phím máy tính không được chấm dấu nhấn.","changelog.bb31c9fcf9cb":"<strong>Theo DAW chỉ có trong DAW.</strong> Ứng dụng độc lập không có công tắc Theo DAW. Trong DAW, nút Nhịp độ giữ nguyên nhịp độ của DAW khi Theo DAW đang bật; tắt nó đi để tự đặt nhịp độ của riêng bạn.","changelog.e77d5ee11f6c":"<strong>Các phím của nhãn Phối khí.</strong> Hoàn tác, Làm lại, Tắt tiếng, Độc tấu và − cùng + của thu phóng là những biểu tượng nhỏ trên dòng nhãn Phối khí, dòng này vẫn ở trong tầm nhìn khi các phím bên dưới cuộn. Tắt tiếng và Độc tấu sáng lên khi đang bật, và mỗi phím có màu riêng khi con trỏ đi qua.","changelog.50f8bc668b74":"<span class=\"release__meta\"><span class=\"release__ver\">v0.9.0</span><time class=\"release__date\" datetime=\"2026-10-17\">2026-10-17</time></span>","changelog.48baf93edf6a":"Bài học vượt ra ngoài piano. Chín khóa học mới nằm cạnh khóa piano trong chế độ bài học: đọc bản nhạc thật, tiết tấu, luyện tai, nhạc lý cho nhà sản xuất với hệ thống số Nashville, sáng tác bài hát, viết lời kèm một nhánh rap và flow, phối khí bài hát và trộn âm, mỗi khóa đi từng ngày từ bài học đầu tiên đến hết phần Cơ bản của nó. Bản thân khóa piano giờ kéo dài đến khoảng cấp 5. Các khóa học sáng tạo được thực hiện trong chế độ xem bài hát, trên làn lời và trong Bàn trộn, và được kiểm tra theo các quy tắc nghề mà bạn có thể gạt sang bên; chế độ xem bài hát có thêm các công cụ của người sáng tác mà các khóa học ấy dùng.","changelog.d6ab249214f0":"<strong>Mười khóa học trong chế độ bài học.</strong> Một bộ chọn khóa học phía trên bản đồ: Đàn piano, Đọc nhạc, Tiết tấu, Luyện tai, Nhạc lý cho nhà sản xuất, Sáng tác bài hát, Viết lời, Rap và flow, Phối khí bài hát và Trộn âm, mỗi khóa giữ riêng những ngày đã đạt, vị trí và các đồng hồ của nó; Tiếp tục mở khóa học bạn đang học dở. Chế độ bài học không bao giờ thay đổi dự án của bạn: những gì một bài học di chuyển sẽ được đặt lại như cũ khi bạn rời đi, và một dự án mà DAW của bạn lưu giữa chừng bài học được lưu đúng như nó vốn có.","changelog.3d47fd1323dd":"<strong>Khóa piano đến khoảng cấp 5.</strong> Ngày 401 đến 1.300: mọi giọng trưởng và thứ với thế bấm ngón chuẩn của nó, gam cách nhau quãng ba và quãng sáu, rải hợp âm bảy, nốt móc kép, các bản nhạc hai bè, sonatina, các bản nhạc Lãng mạn, jazz và song tấu với sân khấu chơi cùng, chơi thuộc lòng, và các mốc kiểm tra ở khoảng cấp 3, 4 và 5.","changelog.7c030855b3fc":"<strong>Đọc nhạc.</strong> Nghe trước khi nhìn, các nốt mốc trên khuông nhạc, đi liền bậc và nhảy quãng, hóa biểu, dòng kẻ phụ và hợp âm, cùng bài thị tấu mới mỗi ngày theo trình độ của bạn, bản nhạc được in đúng giọng của chính bản nhạc ấy.","changelog.101d58d454d2":"<strong>Tiết tấu.</strong> Đếm phách, chia nhỏ phách đến nốt móc kép và chùm ba, đảo phách, swing, nhịp kép và nhịp lẻ, và đa tiết tấu trên một hoặc hai phím, với tiếng tích bớt dần theo từng chặng cho đến khi bạn tự giữ được nhịp.","changelog.9773ae1570b4":"<strong>Luyện tai.</strong> Sân khấu chơi một câu hỏi và bạn trả lời trên các phím, từng câu một: cao hơn hay thấp hơn, quãng, trưởng hay thứ, hợp âm và các thế đảo của chúng, các kết và tiến trình hợp âm dưới dạng đường bè trầm, giai điệu và tiết tấu để chơi lại.","changelog.5fe00efe6b26":"<strong>Nhạc lý cho nhà sản xuất.</strong> Bậc trong gam, quãng, hợp âm và chức năng của chúng, tiến trình hợp âm, các điệu thức, và hệ thống số Nashville — bất kỳ bài hát được tạo nào cũng hiển thị thành bảng hợp âm số, với ô nhịp được chia và hợp âm đẩy sớm.","changelog.bc8ada8b4e41":"<strong>Sáng tác bài hát, Viết lời, Rap và flow, cùng Phối khí bài hát.</strong> Từng ngày từ bài hát đầu tiên của bạn đến một tá bài, ở nhiều thể loại, làm trong chế độ xem bài hát, sổ tay và làn lời: Kiểm tra ở mỗi bước cho biết nó tìm thấy gì và ở đâu, và bất kỳ mục tiêu nào bạn cố ý phá vỡ đều có thể được đánh dấu cố ý.","changelog.71310f87543d":"<strong>Trộn âm.</strong> Gain staging, cân bằng, vị trí stereo, EQ, nén, Phòng và Vọng, và độ to, trên các vòng lặp bài học trong Bàn trộn; Kiểm tra xuất vòng lặp ra và đo các đỉnh, độ to và đỉnh thực (true peak) của nó. Bản trộn của chính dự án bạn không bao giờ bị một bài học thay đổi.","changelog.9373aa367a64":"<strong>Công cụ sáng tác trong chế độ xem bài hát.</strong> Tên bài hát; làn lời dưới giai điệu, mỗi âm tiết dưới nốt của nó với chỗ nhấn được đánh dấu, cuối dòng được tô màu theo vần và mỗi đoạn được gắn nhãn sơ đồ vần; các cụm từ quen thuộc được chỉ ra; một bè được tắt trong một đoạn rồi bật lại; năng lượng của từng đoạn; các phiên bản có tên của bài hát và những gì đã thay đổi từ đó; lưới flow cho rap; và một PDF hồ sơ tác phẩm — bản lead sheet kèm ký hiệu hợp âm và lời, trang lời bài hát và báo cáo kỹ thuật sáng tác.","changelog.b82b445328ca":"<span class=\"release__meta\"><span class=\"release__ver\">v0.8.0</span><time class=\"release__date\" datetime=\"2026-10-16\">2026-10-16</time></span>","changelog.578b5d28a79c":"Chế độ xem bài hát. Handscore giờ viết, dựng và chơi trọn bài hát chứ không chỉ vòng lặp: tạo một bài hát hoàn chỉnh theo hình thức riêng của bất kỳ phong cách nào, hoặc dựng từng đoạn trên dòng thời gian của thẻ Phối khí, và đôi tay cùng bản nhạc chơi nó từ ô nhịp đầu đến ô nhịp cuối, lật trang trong lúc chơi. Bài hát có trống trên một kênh riêng, kéo được vào DAW của bạn cả bài, theo đoạn hay theo clip, và đi kèm điểm độ sẵn sàng thành hit cho thấy, từng mục một, bài hát đáp ứng các quy tắc thực hành của sáng tác ra sao.","changelog.b62ffaa12ca0":"<strong>Thẻ Phối khí.</strong> Nhấn A: dòng thời gian của bài hát gắn vào dưới sân khấu, nên piano, đôi tay và bản nhạc vẫn ở trong tầm nhìn khi bạn dựng, và bài hát phát trong lúc thẻ mở (hoặc khi solo từ bất kỳ thẻ nào). Tạo cả bài hát của một phong cách, chọn một trong các hình thức của nó hoặc hình thức trống, bắt đầu một bài hát trống, hoặc kéo một phong cách từ bảng bên trái lên dòng thời gian.","changelog.3711bc940735":"<strong>Tự tay dựng bài hát.</strong> Thêm, chèn, di chuyển, đổi tên, kéo dài và rút ngắn các đoạn; sao chép và dán clip, tách riêng một clip dùng chung, cho clip vào và ra dần, đặt số ô nhịp nó lặp lại và khóa những clip mà bản thu mới giữ lại. Gieo lại một đoạn, lặp một đoạn, hoặc nhấp đúp vào một clip để nghe riêng nó. Mỗi thay đổi là một bước Hoàn tác.","changelog.3a48bd4ed77a":"<strong>Lấp một ô theo cách của bạn.</strong> Gửi vòng lặp trên sân khấu tới một đoạn, thả một tệp <code>.mid</code> hoặc tệp âm thanh lên một ô từ trình duyệt tệp mới (âm thanh được chuyển thành nốt), hoặc chơi một bản thu vào ô bằng bàn phím MIDI của bạn, có lượng tử hóa nếu muốn.","changelog.bcf7416c3978":"<strong>Sửa nốt của một clip ngay trong bài hát.</strong> Biểu tượng ✎ của clip mở các nốt của nó trong trình sửa bè dưới dòng thời gian: chọn, di chuyển, kéo dài, vẽ, sao chép, dán và xóa nốt ở mọi đoạn dùng chung clip đó, hoặc tách riêng để chỉ đổi một đoạn. Chơi nốt bằng bàn phím MIDI từ ô nhịp bạn chọn.","changelog.bda265df4980":"<strong>Bản nhạc và đôi tay suốt cả bài.</strong> Mỗi tờ nhạc đánh dấu từng đoạn sau một vạch nhịp đôi và hiển thị chỗ nghỉ của một bè thành một ô nhịp kèm con số; qua giữa trang, nửa trên đã lật sang trang kế tiếp, và <em>Đến một đoạn</em> lật mọi tờ nhạc tới đó. Đôi tay tính trước chuyển động qua các đoạn, và bàn tay không có gì để chơi sẽ nhấc khỏi phím và nghỉ.","changelog.6a41964e3d04":"<strong>Hàng trống.</strong> Trống của bài hát chơi trên máy trống của phong cách, trên một kênh riêng trong Bàn trộn. Ở cách bố trí Chơi được, chỉ giữ những gì hai tay và hai chân có thể chơi; Thô giữ mọi cú đánh.","changelog.909f3c615e53":"<strong>Bài hát vào DAW của bạn.</strong> Kéo cả bài với các đoạn làm điểm đánh dấu, một đoạn riêng hoặc một clip, dưới dạng MIDI hoặc âm thanh (tối đa 15 phút). Xuất MIDI và Xuất ra PDF cũng hoạt động từ chế độ xem bài hát.","changelog.e1e1d7a49efa":"<strong>Mơ lại cả bài hát.</strong> Ba phiên bản mới của bài hát theo đúng hình thức, giọng, tempo và nhịp của nó, giữ nguyên các clip bạn đã khóa; giữ lại bản bạn thích.","changelog.9d5296c87435":"<strong>Điểm độ sẵn sàng thành hit.</strong> Một chữ cái và số điểm trên 100 từ mười hai mục kiểm tra về hình thức, các bè và lời của bài hát: hook quay lại bao nhiêu lần và đến sớm thế nào, độ dài intro, độ tương phản giữa các đoạn, tempo hợp phong cách, âm vực và đường nét giai điệu, và lời bài hát vừa nhịp, gieo vần và lặp lại ra sao. Mỗi mục nói nó tìm thấy gì và nhắm tới điều gì, nên điểm số dạy cho bạn; hãy gõ lời của giai điệu vào ô của nó để chấm cả lời. Điểm này cũng có trên trang bìa PDF.","changelog.9960bf9700bd":"<span class=\"release__meta\"><span class=\"release__ver\">v0.7.0</span><time class=\"release__date\" datetime=\"2026-10-16\">2026-10-16</time></span>","changelog.89f5c24a8af1":"Bàn trộn. Giờ đây mỗi bè phát qua kênh riêng của nó — fader, vị trí, EQ, phòng, vọng, nhiệt, một bộ nén và một núm Hạt — vào kênh tổng, có đồng hồ mức, tắt tiếng và độc tấu, tất cả được lưu cùng dự án của bạn. Kéo bất kỳ bè nào, hoặc cả bản trộn, vào DAW của bạn dưới dạng âm thanh, đúng như bạn đang nghe. Tạo hình âm thanh của từng bè bằng trình chỉnh sửa đường bao, và cho bất kỳ bè nào chơi bằng một nhạc cụ VST3 hoặc CLAP của riêng bạn.","changelog.8b1d7b62602b":"<strong>Bàn trộn.</strong> Nhấn M: kênh của mọi bè nằm cạnh nhau cùng kênh tổng — một fader có vạch in theo sát con trỏ của bạn, một đồng hồ mức LED với đèn quá mức, lưới núm (Trầm, Trung, Cao, Phòng, Vọng, Nhiệt), một bộ nén với đèn báo mức nén, vị trí, độc tấu và tắt tiếng. Mỗi thao tác đều nghe được ngay khi đang di chuyển và thành một bước hoàn tác khi bạn thả tay.","changelog.2869671be357":"<strong>Tắt tiếng và độc tấu mượt mà.</strong> Một bè nhỏ dần rồi trở lại trong 30 ms thay vì bị cắt ngang, và độc tấu chỉ cho nghe các bè đang độc tấu — Ctrl+click để thêm một bè.","changelog.fcb6690799bd":"<strong>Núm Hạt.</strong> Trên mọi kênh và trên kênh tổng: từ không có gì ở 0 % đến một đám mây hạt, tiếng vọng và một lớp âm phủ ở 100 %, một âm thanh biến bất kỳ bè nào thành ambient. Hạt giống lấy từ dự án, nên mỗi lần xuất đều cho kết quả giống hệt.","changelog.57a83d56df21":"<strong>Kéo âm thanh.</strong> Tay nắm âm thanh của mỗi bè kéo bè đó thành tệp WAV 24-bit, xuất qua kênh của nó theo nhịp độ của bài; cả bản trộn được kéo đúng như bạn nghe và nêu tên các bè bị bỏ ra.","changelog.b2176c506737":"<strong>Kéo MIDI mang theo bản trộn.</strong> Fader và vị trí của một bè đi vào tệp dưới dạng CC 7 và CC 10, và tay nắm liệt kê những gì MIDI không mang được.","changelog.5b174d5cb7c6":"<strong>Trình chỉnh sửa đường bao.</strong> Các đường bao Âm lượng, Bộ lọc, Cao độ, Vị trí và Hạt của mỗi bộ tạo, mỗi đường đều tắt cho đến khi bạn bật: điểm để kéo, đoạn để uốn cong, một vòng lặp được giữ, thời gian khóa theo nhịp độ, theo lực nhấn và theo phím, kích hoạt lại hoặc liền tiếng, chuyển A/B, hình dạng khởi đầu, sao chép sang bè khác, hoàn tác và làm lại, và một chấm trực tiếp cho mỗi nốt chạy trên đường cong.","changelog.747aa74c96df":"<strong>Nhạc cụ của riêng bạn.</strong> Mỗi bè có thể chơi bằng một nhạc cụ VST3 hoặc CLAP của riêng bạn thay cho nhạc cụ của Handscore: chọn nó trên thẻ hoặc kênh của bè, trong số các nhạc cụ mà lần quét tìm thấy, mở cửa sổ của nó từ đó, và dự án của bạn giữ plugin cùng âm thanh của nó. Mỗi plugin chạy trong tiến trình riêng, nên plugin nào bị sập chỉ tự dừng chính nó, và độ trễ của nó được bù trừ. Đôi tay vẫn ở trên nhạc cụ của Handscore, và bè đó được kéo dưới dạng MIDI.","changelog.ddebf2581fd7":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.0</span><time class=\"release__date\" datetime=\"2026-10-16\">2026-10-16</time></span>","changelog.1d54e0107a4f":"Bài học. Giờ đây Handscore dạy piano, từng ngày một, từ những nốt đầu tiên của bạn đến khoảng trình độ cấp 2: 400 ngày trong hai phần, Nhập môn và Cơ bản, mỗi ngày là một buổi học có hướng dẫn riêng. Đôi tay làm mẫu từng bài tập từ bất kỳ góc nhìn nào, rồi khóa học lắng nghe bạn chơi trên bàn phím MIDI và chỉ đi tiếp khi đã đúng. Bật Đọc to và giọng đọc của chính máy tính sẽ đọc bài cho bạn, mỗi từ sáng lên khi được đọc.","changelog.7cf885e0b28b":"<strong>Bài học ngay trong studio.</strong> Chọn chế độ → Bài học mở khóa piano: bản đồ khóa học và các bước của ngày ở bên trái, sân khấu ở giữa, phần chữ của bài ở bên dưới. Thoát bài học đưa bạn về bài hát bạn đã để lại.","changelog.1c23de3f48f7":"<strong>400 ngày piano.</strong> Nhập môn (ngày 1–90) và Cơ bản (ngày 91–400): tư thế ngồi và dáng tay, các thế năm ngón, đọc khuông nhạc đôi, nhịp điệu, hợp âm, pedal, gam và rải hợp âm, hai tay cùng chơi và những bản nhạc để chơi, với một ngày ôn tập mỗi tuần và bài cũ quay lại khi đến lúc.","changelog.1a00ed521da6":"<strong>Lắng nghe và kiểm tra, theo ba cách.</strong> <em>Thử</em>: các phím cần chơi sáng lên và nhạc chờ bạn. <em>Theo nhịp</em>: đúng tempo sau phần đếm vào, mỗi nốt được so với phách. <em>Chơi trọn bài</em>: chơi từ đầu đến cuối, có phần tóm tắt ở cuối.","changelog.93f77c21d390":"<strong>Nhận xét như của một giáo viên.</strong> Mỗi lần chơi nêu ô nhịp và phách, chỉ cách sửa — một nốt bị bỏ sót, sớm hay muộn, liền hay ngắt, pedal — và nói điều gì đã tốt.","changelog.03b65d4d96a6":"<strong>Công cụ luyện tập.</strong> Lặp lại vài ô nhịp, chơi một tay trong khi sân khấu chơi tay kia, leo thang tempo (lên một bậc sau ba lần chơi sạch, lùi một bậc sau ba lần sai) và xem phần làm mẫu chậm ở bất kỳ góc nhìn nào, có số ngón tay. Tên phím mờ dần khi bạn đã thuộc.","changelog.deb6f2d0e7f9":"<strong>Đọc to.</strong> Tắt cho đến khi bạn bật, và được ghi nhớ. Giọng đọc của máy tính đọc bài, từ đang đọc sáng lên như màn hình karaoke và chữ cuộn theo để luôn hiện trong khung. Phát và tạm dừng bằng phím Cách, dừng, giữ ⏪ hoặc ⏩ để lùi hay tiến, chỉnh tốc độ từ một nửa đến gấp đôi và chọn giọng; một đồng hồ cho biết thời gian đọc đã qua và còn lại.","changelog.b9d693ff0bb1":"<strong>Tiến độ của bạn, được lưu.</strong> Những ngày bạn đã vượt qua, thời gian trong từng bài và trong tất cả, và những ngày bạn đã luyện tập, tính theo ngày, giờ, phút và giây — trên máy tính này, trong ứng dụng độc lập và trong mọi DAW. Tiếp tục mở đúng chỗ bạn đã dừng: ngày, bước và từ.","changelog.2f7168838eb6":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-10-15\">2026-10-15</time></span>","changelog.cb681d22c8c6":"Góc nhìn từ trên và từ bên. Ngắm đôi tay từ phía trước, từ ngay phía trên hoặc từ bên cạnh, và lướt từ góc nhìn này sang góc nhìn khác trong khi nhạc vẫn chơi — phím đàn, đôi tay và các nốt sáng không lỡ một phách nào. Nhìn từ trên, đàn grand đóng nắp và các bản nhạc nằm phẳng trên đó, sẵn sàng để đọc; nhìn từ bên, hình dáng đôi tay hiện rõ: mỗi ngón cong thế nào và mỗi phím nhấn xuống sâu bao nhiêu.","changelog.92ffe6279372":"<strong>Ba góc nhìn: Trước, Trên và Bên.</strong> Xoay núm góc nhìn ở góc trên bên phải sân khấu, hoặc nhấn V để sang góc nhìn kế tiếp và Shift+V để về góc nhìn trước. Dự án của bạn ghi nhớ góc nhìn.","changelog.51b3e3c98cbc":"<strong>Chuyển cảnh liền mạch.</strong> Máy quay lướt từ góc nhìn này sang góc nhìn kế tiếp mà không bao giờ xuyên qua cây đàn, và nhạc vẫn chơi suốt lúc chuyển: mọi phím, mọi bàn tay và mọi nốt sáng đều ở đúng chỗ như khi máy quay đứng yên.","changelog.24e5e2980ffb":"<strong>Trên: phím đàn và đôi tay nhìn từ trên xuống.</strong> Đàn grand gập que chống, hạ giá nhạc nằm phẳng và đóng nắp; các bản nhạc rời giá, chờ phía trên phím đàn rồi nằm cạnh nhau trên nắp đã đóng, đọc xuôi chiều từ chỗ bạn ngồi. Với đàn upright, các bản nhạc nằm trên nắp trên.","changelog.ea29eaefbaec":"<strong>Bên: đôi tay nhìn nghiêng.</strong> Máy quay nhìn dọc bàn phím từ đầu âm cao, ngang tầm phím — hoặc từ đầu âm trầm, với <em>Từ bên trái</em> dưới núm góc nhìn — và các bản nhạc xoay trên giá về phía nó để vẫn đọc được.","changelog.49ab9c89770a":"<strong>Đôi tay từ mọi phía.</strong> Bóng của chúng đổ trên những phím chúng chơi, và nhìn từ trên không đầu ngón nào lún vào phím hay vào thân đàn.","changelog.31bd22333d53":"<strong>Xem gần bản nhạc ở mọi góc nhìn.</strong> Nhấp vào bản nhạc, hoặc nhấn từ 1 đến 5; Esc quay về góc nhìn.","changelog.7acb71645827":"<strong>Mượt mà ở mọi góc nhìn.</strong> Sau mỗi lần đổi góc nhìn hoặc cây đàn, Handscore kiểm tra lại sân khấu vẽ mượt đến đâu, và nếu chậm đi thì giảm chất lượng và báo cho bạn.","changelog.d524626e7e53":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-10-15\">2026-10-15</time></span>","changelog.1afdc18898f2":"Tạo, đọc và kéo thả. Tìm trong 73 thể loại, 1.507 nghệ sĩ hoặc 833 nhà sản xuất, nhấn Tạo, và bốn bè — hợp âm, giai điệu, bè phụ và bè trầm — được viết theo phong cách đó và được đôi tay chơi trên đàn piano. Mỗi bè được in thành bản nhạc thật trên giá nhạc của đàn, bên cạnh tổng phổ, và mỗi nốt sáng lên khi vang. Kéo một bè, hoặc cả bài, thẳng vào DAW của bạn, chỉnh bất kỳ nốt nào trong piano roll riêng của nó, và xuất MIDI hoặc PDF bản nhạc kèm phần ghi công của bạn.","changelog.e5fa15165f43":"<strong>Tạo theo mọi phong cách.</strong> Tìm một thể loại, nghệ sĩ hoặc nhà sản xuất trong bảng bên trái (thẻ của nó ở mép ứng dụng hiện và ẩn bảng) rồi nhấn Tạo, hoặc G. Các nút bên cạnh đặt giọng, thang âm (41 lựa chọn), cảm xúc, nhịp độ (20 đến 999 BPM; kéo con số lên hoặc xuống), độ phức tạp và 4 hoặc 8 ô nhịp, và mỗi nút cho biết bài hát được làm theo gì. <em>Theo DAW</em> viết theo nhịp độ dự án của bạn.","changelog.9b105b8264c8":"<strong>Bốn bè, do đôi tay chơi.</strong> Hợp âm, giai điệu, bè phụ và bè trầm, được sắp cho hai tay (<em>Chơi được</em>) hoặc đúng như đã viết (<em>Nguyên bản</em>). Mỗi lần tạo lấp đầy 4 hoặc 8 ô nhịp của nó, và chuyển từ 4 sang 8 sẽ lặp lại bốn ô đầu.","changelog.99862da9695f":"<strong>Bản nhạc thật.</strong> Mỗi bè được in thành một trang trên giá nhạc, có tiêu đề và số trang, cùng tổng phổ của tất cả các bè bên cạnh. Mỗi đầu nốt sáng lên khi vang dưới con trỏ phát đang chạy, và một bè dài tự lật trang khi chơi. Nhấp vào một bản nhạc, hoặc nhấn 1 đến 5, để đưa nó lại gần; Esc để quay lại.","changelog.4ed6b96e134b":"<strong>Khay bản nhạc.</strong> Dưới sân khấu, mỗi bè có Độc tấu, Tắt tiếng, Khóa và một bản thu mới. Một bè đã khóa sẽ được giữ lại khi bạn tạo lần nữa.","changelog.2b9c198c01ea":"<strong>Kéo vào DAW của bạn.</strong> Kéo một bè, hoặc cả bài với <em>Kéo tất cả</em>, từ bản nhạc của nó vào DAW của bạn dưới dạng MIDI.","changelog.471d0e4ba86d":"<strong>Xuất.</strong> Lưu MIDI của một bè hoặc cả bài, với lực nhấn của từng nốt, mức âm lượng và pan của từng bè, nhịp độ và số chỉ nhịp.","changelog.142257343a9f":"<strong>Xuất ra PDF.</strong> Một PDF bản nhạc có trang bìa: tiêu đề, nhịp độ, giọng và thang âm, độ dài, số ô nhịp, số nốt tổng cộng, theo từng bè và từng trang, và các nhạc cụ. Thêm phần ghi công — tác giả, ca sĩ, nhà sản xuất, các sample bạn đã dùng và nguồn của chúng, hãng thu âm — với tên được gợi ý khi bạn gõ.","changelog.1531fe3dfe30":"<strong>Một thẻ cho mỗi bè.</strong> Sân khấu, Giai điệu, Hợp âm, Bè phụ và Bè trầm ở phía trên; thẻ của mỗi bè có piano roll riêng và một chấm tắt tiếng, Độc tấu và dấu × để xóa bè.","changelog.dc61e3f5b735":"<strong>Chỉnh sửa nốt.</strong> Chọn, di chuyển, kéo dài, xóa, sao chép, dán và nhân bản nốt trong roll của bất kỳ bè nào; nhấp chuột phải và kéo để lấy nốt đi rồi trả lại. Thu từ bàn phím MIDI vào roll sau khi đếm một hoặc hai ô nhịp. Mỗi bè có gain và pan riêng.","changelog.0cb3c4c9fd20":"<strong>Thang âm trên roll.</strong> Thu gọn roll theo thang âm của bài hoặc theo các hàng có nốt; các hàng của thang âm được tô màu và nốt nằm ngoài được đánh dấu.","changelog.0ef6f26c2429":"<strong>Hợp âm một phím.</strong> Bật lên và một phím sẽ chơi một hợp âm 3, 4 hoặc 5 nốt theo giọng của bài, bằng chuột, bàn phím máy tính hoặc bàn phím MIDI.","changelog.d9cada2e85a6":"<strong>Nốt bóng mờ.</strong> Khi bạn vẽ, nốt hoặc hợp âm tiếp theo được gợi ý mờ mờ; Tab giữ lại, một cú nhấp giữ một nốt, và vẽ ở chỗ khác sẽ xóa gợi ý.","changelog.01aa58d9ab50":"<strong>Lời bài hát.</strong> Gõ lời dưới giai điệu hoặc bè phụ, các âm tiết được đánh dấu: chúng được in lên bản nhạc và sáng lên khi được hát. Bộ đếm bên cạnh mỗi dòng cho biết dòng đó có vừa ô nhịp không. Khi bạn gõ, phần còn lại của từ được gợi ý (Tab để nhận) và lỗi chính tả được sửa, trừ khi bạn chạm dấu kiểm hoặc nhấn Shift+Tab để giữ từ của mình.","changelog.407e049442f6":"<strong>Bản thu, Mơ 1–3 và Mơ lại.</strong> Ba phiên bản mới của bất kỳ bè nào bên cạnh bản bạn đang có; chọn một và giữ lại. Mơ lại một bài cổ điển biến nó thành một bài hát mới của riêng bạn.","changelog.a2ae6ec40472":"<strong>Hạt giống.</strong> Mỗi lần tạo hiển thị hạt giống của nó và hạt giống bản thu của từng bè, kèm Sao chép. Dán hạt giống của một bài để tạo lại bài đó, hoặc hạt giống bản thu của một bè để lấy lại bản thu ấy.","changelog.7403cd98e6cb":"<strong>Lịch sử.</strong> Lùi và Tiến qua mọi lần tạo bạn đã làm, mỗi lần được đưa về chính xác và được giữ qua các lần khởi động lại. Một lần tạo mới không bao giờ lặp lại lần cũ.","changelog.3c500d42ebde":"<strong>Bài cổ điển là để học, không phải để lấy.</strong> Chỉ hợp âm của một bài cổ điển mới được đưa ra ngoài. Một bài được tạo có giai điệu, bè phụ hoặc bè trầm giống một giai điệu nổi tiếng sẽ giữ bè đó lại trong ứng dụng, và nói rõ lý do.","changelog.ce67fa868077":"<strong>Hộp thoại phím tắt.</strong> Nhấn ? hoặc nút của nó trên thanh trên cùng để xem mọi phím tắt.","changelog.4ca2136708d7":"<strong>Dự án của bạn ghi nhớ.</strong> Lưu dự án DAW sẽ giữ bài hát, các chỉnh sửa, bản mix, lời, đàn piano, góc nhìn và phần ghi công, và khi mở lại mọi thứ trở về như cũ.","changelog.e60841228886":"<strong>Bản xem trước trên dòng thời gian lớn hơn</strong>, và hiển thị những lời đang được hát vào lúc đó.","changelog.1dca7b1d60db":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.d35d794c003e":"Đôi tay chân thực. Giờ đây một đôi tay chơi piano trên sân khấu của Handscore theo cách một nghệ sĩ piano sẽ chơi — mỗi ngón được chọn cho đoạn nhạc, ngón cái luồn xuống dưới khi chạy gam, một bàn tay nhấc lên vượt qua tay kia khi bản nhạc đòi hỏi bắt chéo tay. Sáu mươi hai bài kinh điển thuộc phạm vi công cộng đã sẵn sàng để học, từ Mary Had a Little Lamb đến Đêm thánh vô cùng và The Star-Spangled Banner, và thanh điều khiển phát bên dưới sân khấu cho phép bạn tạm dừng, tua lại, tua nhanh hoặc kéo đến bất kỳ thời điểm nào, nghe các nốt trong khi di chuyển.","changelog.0390e4a43a0a":"<strong>Đôi tay chân thực trên bàn phím.</strong> Hai bàn tay, kết thúc ở cổ tay, chơi mọi nốt trên cả bốn cây piano: mỗi ngón được chọn như một nghệ sĩ piano sẽ chọn, ngón cái luồn xuống dưới khi chạy gam, vươn tới những hợp âm rộng, ngón cái nằm nghiêng và hơi cong, và một bàn tay nhấc lên vượt qua tay kia để bắt chéo. Khi không có gì đang chơi, đôi tay đặt trên phím, sẵn sàng.","changelog.2c009dbabcfe":"<strong>Thế bấm ngón được tính trước khi một nốt vang lên.</strong> Handscore quyết định tay nào chơi mỗi nốt và bằng ngón nào trước khi nhạc vang lên, nên đôi tay đến đúng lúc phím đi xuống chứ không phải sau đó.","changelog.216f61cb53a3":"<strong>Chọn chế độ.</strong> Nút ở góc trên bên trái (hoặc P) giờ ghi <em>Chọn chế độ</em> và mở các lựa chọn của bạn theo danh mục: Nhạc cụ, Bài kinh điển, Đoạn nhạc và Bài học (sẽ có trong phiên bản sau).","changelog.44952a5f65fd":"<strong>Sáu mươi hai bài kinh điển để học.</strong> Bài hát thiếu nhi, nhạc Giáng sinh và thánh ca Giáng sinh, dân ca, nhạc spiritual và quốc ca, các chủ đề cổ điển và những bản piano được yêu thích — Chopsticks, Jingle Bells, Đêm thánh vô cùng, Ode to Joy, Für Elise, The Entertainer, The Star-Spangled Banner và nhiều bài khác — mỗi bài được soạn cho hai tay, giai điệu ở tay phải và hợp âm ở tay trái. Tìm chúng theo tên bài hoặc nhà soạn nhạc. Tất cả đều thuộc phạm vi công cộng.","changelog.d8fc29c977d3":"<strong>Đoạn nhạc để xem.</strong> Một gam, một ii–V–I, một hợp âm rải và một lần bắt chéo tay, mỗi đoạn là một cái nhìn nhanh vào đôi tay đang làm việc.","changelog.d0ff9a5e5f3f":"<strong>Thanh điều khiển phát.</strong> Phát, tạm dừng, dừng, tua lại và tua nhanh bên dưới sân khấu, với một dòng thời gian hiển thị thời gian của bài và các ô nhịp. Di chuột lên dòng thời gian để xem đôi tay tại thời điểm đó trong một bản xem trước nhỏ. Kéo dọc theo nó, hoặc nhấn giữ tua lại hay tua nhanh, và bạn nghe thấy mọi nốt bạn đi qua, theo cả hai chiều.","changelog.197a823169eb":"<strong>Máy đếm nhịp.</strong> Bật nó lên và một tiếng tích đánh dấu mỗi phách, phách đầu của mỗi ô nhịp cao hơn, trong khi các chấm bên cạnh chữ <em>M</em> của nó hiển thị phách.","changelog.f94e5b4b235f":"<strong>Phím cách để phát và tạm dừng.</strong>","changelog.dd397e7c80b2":"<strong>Nút nhạc cụ giờ là Chọn chế độ</strong>, và cây piano bạn chọn được đánh dấu <em>Hiện tại</em> trong Nhạc cụ.","changelog.c59c86e0cd28":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.14c84d5c455f":"Những cây piano thật. Giờ đây sân khấu của Handscore có bốn cây piano — một cây đại dương cầm biểu diễn, một cây đại dương cầm phòng khách, một cây piano đứng phòng thu và một cây piano đứng cũ kỹ từ quán rượu miền Viễn Tây — mỗi cây được chiếu sáng như trong phòng thu và mỗi cây có giọng riêng. Nhấp vào một phím hoặc chơi từ DAW của bạn và cây piano sẽ cất tiếng: phím đi xuống, tên của nó mờ dần, và pedal sustain giữ lại những nốt bạn buông ra. Bộ chọn piano cho phép bạn nghe một cây piano trước khi chọn nó.","changelog.a8f76e859570":"<strong>Bốn cây piano thật.</strong> Grand Piano, Acoustic Piano, Upright Piano và Honky-Tonk Piano, mỗi cây có hình dáng, lớp hoàn thiện và âm thanh riêng, ở cả hai giao diện.","changelog.6f544a8bd67f":"<strong>Chơi các phím.</strong> Nhấp vào một phím để nghe nó, hoặc lướt qua các phím để chơi lần lượt từng phím. MIDI từ DAW của bạn chơi cây piano và làm các phím của nó chuyển động, còn pedal sustain giữ những nốt bạn buông ra cho đến khi bạn nhấc chân khỏi pedal.","changelog.3f265130a08f":"<strong>Phím chuyển động như phím đàn piano.</strong> Mỗi phím đi xuống bằng cách xoay trên thanh cân bằng của nó, được chơi càng mạnh thì xuống càng nhanh, và tên của phím mờ đi khi phím đang xuống rồi hiện lại khi phím nâng lên.","changelog.7fd2c1ed940d":"<strong>Bộ chọn piano.</strong> Nút nhạc cụ ở góc trên bên trái (hoặc P) mở ra bốn thẻ. <em>Nghe thử</em> chơi một câu nhạc ngắn trên cây piano đó mà không đổi đàn; <em>Chọn</em> đưa nó lên sân khấu, chuyển tiếp mượt mà từ cây trước đó. Lựa chọn của bạn được lưu cùng dự án.","changelog.72aa386a33ff":"<strong>Chất lượng vừa với máy tính của bạn.</strong> Handscore đo xem máy tính của bạn vẽ sân khấu nhanh đến đâu và chọn mức chất lượng mà máy có thể duy trì mượt mà.","changelog.1246fc93bca0":"Đã sửa","changelog.58e041aeca75":"<strong>Phím theo kịp ngay cả trên máy tính đang bận.</strong> Một phím được chơi khi máy tính vẽ chậm có thể vẫn ở trên, hoặc tên của nó vẫn mờ một nửa; giờ đây phím luôn dừng đúng ở trạng thái mà cách chơi của bạn để lại.","changelog.e6eef73c000a":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-10-12\">2026-10-12</time></span>","changelog.ff94e0b1d59f":"Nền móng. Freally Handscore tải được dưới dạng plugin CLAP và VST3 lẫn ứng dụng độc lập, đề nghị bạn chấp nhận giấy phép, và mở ra trên sân khấu của nó: một bàn phím 88 phím theo đúng kích thước của một cây đàn piano thật, với tên của mọi phím ở mặt trước. Hiện chưa có gì được tạo ra — điều đó sẽ đến cùng những cây piano thật và đôi tay.","changelog.37cee751dc57":"<strong>Plugin và ứng dụng độc lập.</strong> CLAP và VST3 trên Windows (AU được dựng trên máy Mac), và một ứng dụng độc lập mang biểu tượng của Handscore trên thanh tiêu đề và thanh tác vụ.","changelog.bf0d03d43bfd":"<strong>Thỏa thuận cấp phép đến trước tiên.</strong> Cho đến khi bạn đồng ý, Handscore không làm gì. Câu trả lời của bạn được lưu trên máy tính của bạn và dùng chung cho mọi bản đang mở, trong mọi DAW và trong ứng dụng độc lập.","changelog.28bc52fb055e":"<strong>Sân khấu.</strong> Một bàn phím 88 phím, từ A0 đến C8, theo đúng kích thước của một cây đàn piano thật, trải kín chiều rộng cửa sổ. Tên của mỗi phím nằm ở mặt trước của nó — phím trắng in mực tối, phím đen in màu trắng — và ẩn đi khi phím đang được nhấn.","changelog.d51fdbedfc0e":"<strong>Sáng và tối.</strong> Công tắc ở góc trên bên phải; Handscore ghi nhớ lựa chọn của bạn.","changelog.9e0609310c1a":"<strong>Mười tám ngôn ngữ.</strong> Handscore khởi động bằng ngôn ngữ hệ thống của bạn.","changelog.f1cf7c9dfaa8":"<strong>Chế độ xem 3D biết báo khi không thể vẽ.</strong> Một cửa sổ không có WebGL 2 sẽ giải thích cách bật nó lên thay vì không hiển thị gì.","changelog.0fe089d138d3":"<strong>Sự cố được lưu lại, không bao giờ gửi đi.</strong> Nếu Handscore có lúc dừng đột ngột, một báo cáo ngắn sẽ được lưu trên máy tính của bạn cho lần khởi chạy tiếp theo. Không có gì rời khỏi máy tính của bạn trừ khi bạn chọn báo cáo sự cố."};
